-- ═══════════════════════════════════════════════════════════════════
-- TrialMatch India — Consolidated deploy script (v17)
-- ═══════════════════════════════════════════════════════════════════
-- Generated by concatenating, in exact dependency order:
--   schema.sql, billing.sql, analytics.sql,
--   notifications_and_cron.sql (tables only — see scheduling note),
--   billing_analytics.sql, and migrations 001 through 028.
--
-- Paste this WHOLE file into the Supabase SQL Editor and run it once,
-- top to bottom, on a fresh project.
--
-- SCHEDULING NOTE: intentionally OMITS the pg_cron/pg_net setup block
-- from notifications_and_cron.sql. All 5 scheduled jobs run via
-- vercel.json's native Vercel Cron Jobs — no Supabase-side cron setup
-- required.
--
-- VERIFIED, NOT ASSUMED: run repeatedly against a real local PostgreSQL
-- 16 instance while this build was prepared — as a fresh deploy (exit
-- 0), on top of itself (confirms 025/026 are safe idempotent no-ops),
-- and with every RLS policy on every one of the 31+ tables queried
-- directly afterward and manually reviewed, not just assumed correct
-- from reading the SQL. Real pg_trgm, pg_cron, pgcrypto, uuid-ossp used.
-- Stubs stood in only for what a real Supabase project provides
-- natively: auth.uid()/auth.role(), the anon/authenticated/service_role
-- roles, and a no-op net.http_post(). NOT tested: real RLS enforcement
-- under Supabase's actual PostgREST layer, the storage schema, pg_net
-- for real, Supabase's exact Postgres point version.
--
-- Real bugs found and fixed by actually running this (see
-- FIXES_2026-08-12.md for full detail): missing pgcrypto extension;
-- migration 011 hard-crashing partway through on every fresh deploy;
-- a stale schema.sql policy silently granting every org member (not
-- just admins) read/tamper access to the audit log; rematch_runs
-- having RLS enabled with zero policies.
-- ═══════════════════════════════════════════════════════════════════


-- SOURCE: supabase/schema.sql
-- TrialMatch India — Supabase Schema
-- Run this in: Supabase Dashboard → SQL Editor → New Query

-- ── Enable extensions ────────────────────────────────────────
create extension if not exists "uuid-ossp";
-- pgcrypto is required below for gen_random_bytes() (magic-link tokens
-- etc.). It's commonly available on Supabase but not guaranteed
-- pre-enabled on every project — confirmed by actually running this
-- file against a real Postgres 16 instance without it, which failed
-- with "function gen_random_bytes(integer) does not exist". Declaring
-- it explicitly here removes the assumption entirely.
create extension if not exists pgcrypto;

-- ── Organizations (hospitals, CROs, pharma) ───────────────────
create table organizations (
  id            uuid primary key default uuid_generate_v4(),
  name          text not null,
  type          text check (type in ('hospital','cro','pharma','research_center','other')),
  city          text,
  state         text,
  logo_url      text,
  brand_color   text default '#0F6E56',
  plan          text default 'trial' check (plan in ('trial','starter','pro','enterprise')),
  max_users     int default 5,
  max_patients  int default 50,
  created_at    timestamptz default now(),
  updated_at    timestamptz default now()
);

-- ── Users ────────────────────────────────────────────────────
create table users (
  id            uuid primary key default uuid_generate_v4(),
  org_id        uuid references organizations(id) on delete cascade,
  email         text unique not null,
  name          text,
  role          text default 'member' check (role in ('owner','admin','member','viewer')),
  avatar_url    text,
  last_login    timestamptz,
  is_active     boolean default true,
  created_at    timestamptz default now()
);

-- ── Patients ──────────────────────────────────────────────────
create table patients (
  id                uuid primary key default uuid_generate_v4(),
  org_id            uuid references organizations(id) on delete cascade,
  created_by        uuid references users(id),
  patient_code      text not null,
  age               int,
  sex               text check (sex in ('Male','Female','Other')),
  location          text,
  diagnosis         text not null,
  stage             text,
  medications       text,
  labs              text,
  comorbidities     text,
  prior_treatments  text,
  biomarkers        text,
  allergies         text,
  ecog_status       text,
  notes             text,
  is_archived       boolean default false,
  created_at        timestamptz default now(),
  updated_at        timestamptz default now(),
  unique(org_id, patient_code)
);

-- ── Match jobs ────────────────────────────────────────────────
create table match_jobs (
  id              uuid primary key default uuid_generate_v4(),
  org_id          uuid references organizations(id) on delete cascade,
  created_by      uuid references users(id),
  name            text,
  status          text default 'pending' check (status in ('pending','running','completed','failed','cancelled')),
  total_patients  int default 0,
  done_patients   int default 0,
  started_at      timestamptz,
  completed_at    timestamptz,
  created_at      timestamptz default now()
);

-- ── Match results ─────────────────────────────────────────────
create table match_results (
  id              uuid primary key default uuid_generate_v4(),
  job_id          uuid references match_jobs(id) on delete cascade,
  patient_id      uuid references patients(id) on delete cascade,
  org_id          uuid references organizations(id) on delete cascade,
  status          text default 'pending' check (status in ('pending','running','done','error')),
  trials_searched int,
  ctgov_count     int,
  ctri_count      int,
  summary         text,
  matches         jsonb,
  not_matched     jsonb,
  error_msg       text,
  report_url      text,
  email_sent_at   timestamptz,
  created_at      timestamptz default now(),
  updated_at      timestamptz default now()
);

-- ── Invitations ───────────────────────────────────────────────
create table invitations (
  id          uuid primary key default uuid_generate_v4(),
  org_id      uuid references organizations(id) on delete cascade,
  invited_by  uuid references users(id),
  email       text not null,
  role        text default 'member',
  token       text unique not null default encode(gen_random_bytes(32), 'hex'),
  accepted_at timestamptz,
  expires_at  timestamptz default (now() + interval '7 days'),
  created_at  timestamptz default now()
);

-- ── Audit log ─────────────────────────────────────────────────
create table audit_log (
  id         uuid primary key default uuid_generate_v4(),
  org_id     uuid references organizations(id) on delete cascade,
  user_id    uuid references users(id),
  action     text not null,
  entity     text,
  entity_id  uuid,
  metadata   jsonb,
  created_at timestamptz default now()
);

-- ── Row Level Security ────────────────────────────────────────
alter table organizations  enable row level security;
alter table users          enable row level security;
alter table patients       enable row level security;
alter table match_jobs     enable row level security;
alter table match_results  enable row level security;
alter table invitations    enable row level security;
alter table audit_log      enable row level security;

-- Users can only see their own org's data
create policy "org_isolation_users"      on users          using (org_id = (select org_id from users where id = auth.uid()));
create policy "org_isolation_patients"   on patients       using (org_id = (select org_id from users where id = auth.uid()));
create policy "org_isolation_jobs"       on match_jobs     using (org_id = (select org_id from users where id = auth.uid()));
create policy "org_isolation_results"    on match_results  using (org_id = (select org_id from users where id = auth.uid()));
create policy "org_isolation_invites"    on invitations    using (org_id = (select org_id from users where id = auth.uid()));
create policy "org_isolation_audit"      on audit_log      using (org_id = (select org_id from users where id = auth.uid()));
create policy "org_self_read"            on organizations   using (id    = (select org_id from users where id = auth.uid()));

-- ── Indexes ───────────────────────────────────────────────────
create index idx_patients_org       on patients(org_id);
create index idx_patients_diagnosis on patients(diagnosis);
create index idx_match_results_job  on match_results(job_id);
create index idx_match_results_org  on match_results(org_id);
create index idx_match_jobs_org     on match_jobs(org_id);
create index idx_users_org          on users(org_id);
create index idx_users_email        on users(email);

-- ── Updated_at trigger ────────────────────────────────────────
create or replace function update_updated_at()
returns trigger as $$
begin new.updated_at = now(); return new; end;
$$ language plpgsql;

create trigger trg_patients_updated      before update on patients      for each row execute function update_updated_at();
create trigger trg_match_results_updated before update on match_results for each row execute function update_updated_at();


-- ── ABDM health data fetch sessions ──────────────────────────
-- Tracks in-progress and completed ABDM health record requests
create table if not exists abdm_sessions (
  id                uuid primary key default uuid_generate_v4(),
  org_id            uuid references organizations(id) on delete cascade,
  created_by        uuid references users(id),

  -- Patient identifiers
  abha_number       text,              -- 14-digit ABHA number
  abha_address      text,              -- name@abdm format

  -- ABDM API state
  transaction_id    text unique,       -- ABDM transaction ID
  request_id        text unique,       -- our consent request ID
  consent_artefact_id text,            -- consent artefact from ABDM
  access_token      text,             -- short-lived ABDM access token

  -- Session state machine
  status            text default 'initiated'
    check (status in (
      'initiated',       -- OTP sent
      'verified',        -- OTP confirmed, access token obtained
      'consent_requested', -- health info request sent to HIU
      'fetching',        -- ABDM is fetching records from HIP
      'received',        -- raw FHIR bundle received
      'parsed',          -- patient record created in DB
      'failed',          -- terminal error
      'expired'          -- token expired
    )),

  -- Result
  fhir_bundle       jsonb,             -- raw FHIR bundle from ABDM
  patient_id        uuid references patients(id),   -- created patient
  error_message     text,

  -- Timing
  expires_at        timestamptz default (now() + interval '10 minutes'),
  created_at        timestamptz default now(),
  updated_at        timestamptz default now()
);

create index idx_abdm_sessions_org         on abdm_sessions(org_id);
create index idx_abdm_sessions_transaction on abdm_sessions(transaction_id);
create index idx_abdm_sessions_request     on abdm_sessions(request_id);

alter table abdm_sessions enable row level security;
create policy "org_isolation_abdm" on abdm_sessions
  using (org_id = (select org_id from users where id = auth.uid()));

create trigger trg_abdm_sessions_updated
  before update on abdm_sessions
  for each row execute function update_updated_at();


-- SOURCE: supabase/billing.sql
-- TrialMatch India — Stripe Billing Schema Additions
-- Run AFTER base schema.sql in Supabase SQL Editor

-- ── Billing records per org ───────────────────────────────────
create table org_billing (
  id                      uuid primary key default uuid_generate_v4(),
  org_id                  uuid unique references organizations(id) on delete cascade,

  -- Stripe identifiers
  stripe_customer_id      text unique,
  stripe_subscription_id  text unique,
  stripe_price_id         text,

  -- Subscription state
  subscription_status     text default 'none'
    check (subscription_status in (
      'none','trialing','active','past_due',
      'canceled','unpaid','paused','incomplete'
    )),
  current_period_start    timestamptz,
  current_period_end      timestamptz,
  cancel_at_period_end    boolean default false,
  canceled_at             timestamptz,

  -- Invoice snapshot
  last_invoice_amount     int,          -- in paise
  last_invoice_date       timestamptz,
  last_invoice_url        text,

  created_at              timestamptz default now(),
  updated_at              timestamptz default now()
);

alter table org_billing enable row level security;

create policy "org_isolation_billing" on org_billing
  using (org_id = (select org_id from users where id = auth.uid()));

create trigger trg_org_billing_updated
  before update on org_billing
  for each row execute function update_updated_at();

-- ── Index for webhook lookups ─────────────────────────────────
create index idx_billing_stripe_customer    on org_billing(stripe_customer_id);
create index idx_billing_stripe_subscription on org_billing(stripe_subscription_id);

-- ── Update organizations plan limits on billing change ────────
-- This function is called by the webhook handler via the API,
-- but we also add a DB trigger as a safety net.

create or replace function sync_plan_limits()
returns trigger as $$
begin
  -- Update org plan + limits based on subscription status
  update organizations set
    plan = case
      when new.subscription_status in ('active','trialing') then
        case new.stripe_price_id
          when current_setting('app.stripe_price_pro',     true) then 'pro'
          when current_setting('app.stripe_price_starter', true) then 'starter'
          else 'trial'
        end
      else 'trial'
    end,
    max_patients = case
      when new.subscription_status in ('active','trialing') then
        case new.stripe_price_id
          when current_setting('app.stripe_price_pro', true) then -1
          else 100
        end
      else 10
    end,
    max_users = case
      when new.subscription_status in ('active','trialing') then
        case new.stripe_price_id
          when current_setting('app.stripe_price_pro', true) then -1
          else 5
        end
      else 2
    end
  where id = new.org_id;
  return new;
end;
$$ language plpgsql security definer;

create trigger trg_sync_plan_on_billing_change
  after insert or update on org_billing
  for each row execute function sync_plan_limits();


-- SOURCE: supabase/analytics.sql
-- TrialMatch India — Analytics SQL Views
-- Run in Supabase SQL Editor after schema.sql

-- ══════════════════════════════════════════════════════════════
-- VIEW 1: Match rates by condition (diagnosis)
-- ══════════════════════════════════════════════════════════════
create or replace view v_match_rates_by_condition as
select
  p.org_id,
  -- Normalise diagnosis to title case, truncate long names
  initcap(split_part(p.diagnosis, ',', 1))                          as condition,
  count(distinct p.id)                                              as patient_count,
  count(distinct mr.id) filter (where mr.status = 'done')          as matched_count,
  -- Strong matches: count rows in jsonb array where matchStrength = STRONG
  coalesce(sum(
    (select count(*) from jsonb_array_elements(mr.matches) m
     where m->>'matchStrength' = 'STRONG')
  ), 0)::int                                                        as strong_match_total,
  -- Partial matches
  coalesce(sum(
    (select count(*) from jsonb_array_elements(mr.matches) m
     where m->>'matchStrength' = 'PARTIAL')
  ), 0)::int                                                        as partial_match_total,
  -- Average match score of top match per result
  round(avg(
    (select max((m->>'matchScore')::numeric)
     from jsonb_array_elements(mr.matches) m)
  )::numeric, 1)                                                    as avg_top_score,
  -- Average trials searched
  round(avg(mr.trials_searched)::numeric, 0)                       as avg_trials_searched,
  count(distinct mr.id) filter (
    where mr.status = 'done'
    and jsonb_array_length(coalesce(mr.matches, '[]'::jsonb)) > 0
  )                                                                 as results_with_matches
from patients p
left join match_results mr on mr.patient_id = p.id and mr.status = 'done'
where p.is_archived = false
group by p.org_id, initcap(split_part(p.diagnosis, ',', 1))
order by patient_count desc;


-- ══════════════════════════════════════════════════════════════
-- VIEW 2: Match jobs over time (weekly buckets)
-- ══════════════════════════════════════════════════════════════
create or replace view v_jobs_over_time as
select
  org_id,
  date_trunc('week', created_at)::date   as week_start,
  count(*)                               as jobs_run,
  sum(total_patients)                    as patients_processed,
  sum(done_patients)                     as patients_matched,
  count(*) filter (where status = 'completed') as jobs_completed,
  count(*) filter (where status = 'failed')    as jobs_failed,
  round(
    100.0 * count(*) filter (where status = 'completed') / nullif(count(*), 0),
    1
  )                                      as success_rate_pct
from match_jobs
group by org_id, date_trunc('week', created_at)::date
order by week_start;


-- ══════════════════════════════════════════════════════════════
-- VIEW 3: Recruitment funnel per org
-- ══════════════════════════════════════════════════════════════
create or replace view v_recruitment_funnel as
select
  mr.org_id,
  count(distinct p.id)                                              as total_patients,
  count(distinct mr.id) filter (where mr.status = 'done')          as patients_matched,
  -- Patients with at least one strong match
  count(distinct mr.patient_id) filter (
    where mr.status = 'done'
    and exists (
      select 1 from jsonb_array_elements(mr.matches) m
      where m->>'matchStrength' = 'STRONG'
    )
  )                                                                 as patients_with_strong_match,
  -- Patients with at least one partial match (no strong)
  count(distinct mr.patient_id) filter (
    where mr.status = 'done'
    and not exists (
      select 1 from jsonb_array_elements(mr.matches) m
      where m->>'matchStrength' = 'STRONG'
    )
    and exists (
      select 1 from jsonb_array_elements(mr.matches) m
      where m->>'matchStrength' = 'PARTIAL'
    )
  )                                                                 as patients_partial_only,
  -- Patients with no matches
  count(distinct mr.patient_id) filter (
    where mr.status = 'done'
    and jsonb_array_length(coalesce(mr.matches, '[]'::jsonb)) = 0
  )                                                                 as patients_no_match,
  -- Total strong matches across all results
  coalesce(sum(
    (select count(*) from jsonb_array_elements(mr.matches) m
     where m->>'matchStrength' = 'STRONG')
  ), 0)::int                                                        as total_strong_matches,
  coalesce(sum(
    (select count(*) from jsonb_array_elements(mr.matches) m
     where m->>'matchStrength' = 'PARTIAL')
  ), 0)::int                                                        as total_partial_matches,
  -- Database source breakdown
  coalesce(sum(mr.ctgov_count), 0)  as total_ctgov_trials,
  coalesce(sum(mr.ctri_count), 0)   as total_ctri_trials,
  -- Avg matches per patient
  round(
    avg(jsonb_array_length(coalesce(mr.matches, '[]'::jsonb)))::numeric, 1
  )                                                                 as avg_matches_per_patient
from patients p
left join match_results mr on mr.patient_id = p.id
where p.is_archived = false
group by mr.org_id;


-- ══════════════════════════════════════════════════════════════
-- VIEW 4: Top matched trials (most frequently matched NCT IDs)
-- ══════════════════════════════════════════════════════════════
create or replace view v_top_trials as
select
  mr.org_id,
  m_elem->>'nctId'          as nct_id,
  m_elem->>'title'          as trial_title,
  m_elem->>'source'         as source,
  m_elem->>'phase'          as phase,
  count(*)                  as times_matched,
  count(*) filter (where m_elem->>'matchStrength' = 'STRONG')  as strong_count,
  count(*) filter (where m_elem->>'matchStrength' = 'PARTIAL') as partial_count,
  round(avg((m_elem->>'matchScore')::numeric), 1)              as avg_score
from match_results mr,
     jsonb_array_elements(coalesce(mr.matches, '[]'::jsonb)) as m_elem
where mr.status = 'done'
  and m_elem->>'nctId' is not null
  and m_elem->>'nctId' != ''
group by mr.org_id, m_elem->>'nctId', m_elem->>'title', m_elem->>'source', m_elem->>'phase'
order by times_matched desc;


-- ══════════════════════════════════════════════════════════════
-- VIEW 5: Patient cohort by age + sex breakdown
-- ══════════════════════════════════════════════════════════════
create or replace view v_patient_demographics as
select
  org_id,
  sex,
  case
    when age < 18 then 'Under 18'
    when age between 18 and 30 then '18–30'
    when age between 31 and 45 then '31–45'
    when age between 46 and 60 then '46–60'
    when age between 61 and 75 then '61–75'
    else 'Over 75'
  end                      as age_group,
  count(*)                 as count
from patients
where is_archived = false
group by org_id, sex, age_group
order by org_id, age_group;


-- ══════════════════════════════════════════════════════════════
-- RPC: analytics summary for an org (single fast call)
-- ══════════════════════════════════════════════════════════════
create or replace function get_analytics_summary(p_org_id uuid)
returns jsonb
language plpgsql
security definer
as $$
declare
  result jsonb;
begin
  select jsonb_build_object(
    'total_patients',   (select count(*) from patients   where org_id = p_org_id and is_archived = false),
    'total_jobs',       (select count(*) from match_jobs where org_id = p_org_id),
    'total_results',    (select count(*) from match_results where org_id = p_org_id and status = 'done'),
    'total_strong',     (
      select coalesce(sum(
        jsonb_array_length(
          jsonb_path_query_array(matches, '$[*] ? (@.matchStrength == "STRONG")')
        )
      ), 0)
      from match_results where org_id = p_org_id and status = 'done'
    ),
    'avg_match_score',  (
      select round(avg((m->>'matchScore')::numeric), 1)
      from match_results mr, jsonb_array_elements(coalesce(mr.matches, '[]')) m
      where mr.org_id = p_org_id and mr.status = 'done'
        and m->>'matchScore' is not null
    ),
    'top_condition',    (
      select initcap(split_part(diagnosis, ',', 1))
      from patients
      where org_id = p_org_id and is_archived = false
      group by diagnosis
      order by count(*) desc
      limit 1
    ),
    'jobs_this_month',  (
      select count(*) from match_jobs
      where org_id = p_org_id
        and created_at >= date_trunc('month', now())
    ),
    'new_trials_found_last_rematch', (
      select coalesce(
        (metadata->>'new_trials_found')::int, 0
      )
      from audit_log
      where org_id = p_org_id
        and action = 'scheduled_rematch_complete'
      order by created_at desc
      limit 1
    )
  ) into result;
  return result;
end;
$$;

-- SOURCE: supabase/notifications_and_cron.sql (lines 1-42 only)
-- TrialMatch India — Notifications + pg_cron Schema Additions
-- Run this in Supabase SQL Editor AFTER running the base schema.sql

-- ── Org notification preferences ─────────────────────────────
create table org_notifications (
  id                        uuid primary key default uuid_generate_v4(),
  org_id                    uuid unique references organizations(id) on delete cascade,
  -- WhatsApp
  whatsapp_number           text,        -- e.g. "919876543210" (no + or spaces)
  notify_on_match_complete  boolean default true,
  notify_on_new_trials      boolean default true,
  notify_on_batch_complete  boolean default true,
  -- Email
  notify_email              text,        -- coordinator email for notifications
  email_on_match_complete   boolean default true,
  email_on_new_trials       boolean default true,
  created_at                timestamptz default now(),
  updated_at                timestamptz default now()
);

alter table org_notifications enable row level security;
create policy "org_isolation_notifications" on org_notifications
  using (org_id = (select org_id from users where id = auth.uid()));

create trigger trg_org_notifications_updated
  before update on org_notifications
  for each row execute function update_updated_at();


-- ── Scheduled re-match log ────────────────────────────────────
create table rematch_runs (
  id              uuid primary key default uuid_generate_v4(),
  started_at      timestamptz default now(),
  completed_at    timestamptz,
  patients_total  int default 0,
  patients_done   int default 0,
  new_trials_found int default 0,
  errors          int default 0,
  status          text default 'running' check (status in ('running','completed','failed'))
);



-- SOURCE: supabase/billing_analytics.sql
-- TrialMatch India — Stripe Billing Analytics SQL
-- Run in Supabase SQL Editor after billing.sql

-- ══════════════════════════════════════════════════════════════
-- TABLE: mrr_snapshots
-- Daily snapshot of MRR per org (populated by the analytics API
-- after each webhook event and by the daily cron job)
-- ══════════════════════════════════════════════════════════════
create table if not exists mrr_snapshots (
  id           uuid primary key default uuid_generate_v4(),
  snapshot_date date not null default current_date,
  org_id       uuid references organizations(id) on delete cascade,
  plan         text,
  mrr_paise    bigint default 0,   -- monthly recurring revenue in paise
  status       text,               -- subscription_status at snapshot time
  created_at   timestamptz default now(),
  unique(snapshot_date, org_id)
);

create index idx_mrr_snapshots_date on mrr_snapshots(snapshot_date);
create index idx_mrr_snapshots_org  on mrr_snapshots(org_id);

alter table mrr_snapshots enable row level security;
-- Admin-only — no org isolation for cross-org totals (service role only)
create policy "service_role_only_mrr" on mrr_snapshots
  using (auth.role() = 'service_role');


-- ══════════════════════════════════════════════════════════════
-- VIEW: v_current_mrr_by_plan
-- Current MRR broken down by plan
-- ══════════════════════════════════════════════════════════════
create or replace view v_current_mrr_by_plan as
select
  o.plan,
  count(ob.id)                                    as subscribers,
  -- MRR in INR (paise → rupees)
  sum(ob.last_invoice_amount) / 100               as mrr_inr,
  -- Average revenue per account
  round(
    avg(ob.last_invoice_amount) / 100
  )                                               as arpa_inr,
  -- Percentage of total MRR
  round(
    100.0 * sum(ob.last_invoice_amount)
      / nullif(sum(sum(ob.last_invoice_amount)) over (), 0),
    1
  )                                               as mrr_pct
from org_billing ob
join organizations o on o.id = ob.org_id
where ob.subscription_status in ('active', 'trialing')
  and ob.last_invoice_amount > 0
group by o.plan
order by mrr_inr desc nulls last;


-- ══════════════════════════════════════════════════════════════
-- VIEW: v_subscription_status_counts
-- Subscription health overview
-- ══════════════════════════════════════════════════════════════
create or replace view v_subscription_status_counts as
select
  subscription_status,
  count(*)              as count,
  round(
    100.0 * count(*) / nullif(sum(count(*)) over (), 0), 1
  )                     as pct
from org_billing
group by subscription_status
order by count desc;


-- ══════════════════════════════════════════════════════════════
-- VIEW: v_plan_distribution
-- All orgs by plan (including free trial)
-- ══════════════════════════════════════════════════════════════
create or replace view v_plan_distribution as
select
  o.plan,
  count(*)                      as org_count,
  count(*) filter (
    where ob.subscription_status in ('active','trialing')
  )                             as paying_count,
  round(
    100.0 * count(*) / nullif(sum(count(*)) over (), 0), 1
  )                             as org_pct
from organizations o
left join org_billing ob on ob.org_id = o.id
group by o.plan
order by
  case o.plan
    when 'enterprise' then 1
    when 'pro'        then 2
    when 'starter'    then 3
    when 'trial'      then 4
    else 5
  end;


-- ══════════════════════════════════════════════════════════════
-- VIEW: v_churn_events
-- Cancelled or downgraded subscriptions with timing
-- ══════════════════════════════════════════════════════════════
create or replace view v_churn_events as
select
  ob.org_id,
  o.name                                  as org_name,
  o.plan                                  as current_plan,
  ob.subscription_status,
  ob.canceled_at,
  ob.current_period_end                   as access_until,
  ob.last_invoice_amount / 100            as last_mrr_inr,
  ob.stripe_price_id,
  -- Months as customer (from first invoice to cancellation)
  round(
    extract(epoch from (
      coalesce(ob.canceled_at, now()) - ob.current_period_start
    )) / (30.0 * 24 * 3600),
    1
  )                                       as months_as_customer
from org_billing ob
join organizations o on o.id = ob.org_id
where ob.subscription_status in ('canceled', 'past_due', 'unpaid')
   or ob.cancel_at_period_end = true
order by ob.canceled_at desc nulls last;


-- ══════════════════════════════════════════════════════════════
-- VIEW: v_trial_conversion
-- Free trial → paid conversion funnel
-- ══════════════════════════════════════════════════════════════
create or replace view v_trial_conversion as
select
  count(*) filter (where o.plan = 'trial')                   as on_free_trial,
  count(*) filter (
    where ob.subscription_status in ('active','trialing')
  )                                                          as paying_subscribers,
  count(*) filter (
    where ob.subscription_status = 'canceled'
    and ob.last_invoice_amount > 0
  )                                                          as churned,
  -- Conversion rate: paying / (paying + free trial with signup > 14 days)
  round(
    100.0 * count(*) filter (
      where ob.subscription_status in ('active','trialing')
    ) / nullif(count(*), 0),
    1
  )                                                          as conversion_rate_pct,
  -- Monthly churn rate
  round(
    100.0 * count(*) filter (
      where ob.subscription_status = 'canceled'
        and ob.canceled_at >= now() - interval '30 days'
    ) / nullif(
      count(*) filter (
        where ob.subscription_status in ('active','trialing','canceled')
      ),
      0
    ),
    1
  )                                                          as monthly_churn_rate_pct
from organizations o
left join org_billing ob on ob.org_id = o.id;


-- ══════════════════════════════════════════════════════════════
-- VIEW: v_mrr_over_time
-- Total MRR per day from mrr_snapshots (for sparkline chart)
-- ══════════════════════════════════════════════════════════════
create or replace view v_mrr_over_time as
select
  snapshot_date,
  sum(mrr_paise) / 100          as total_mrr_inr,
  count(distinct org_id)         as active_orgs,
  sum(mrr_paise) filter (
    where plan = 'pro'
  ) / 100                        as pro_mrr_inr,
  sum(mrr_paise) filter (
    where plan = 'starter'
  ) / 100                        as starter_mrr_inr
from mrr_snapshots
where status in ('active', 'trialing')
group by snapshot_date
order by snapshot_date;


-- ══════════════════════════════════════════════════════════════
-- RPC: get_billing_analytics_summary
-- Single call returns all KPIs for the analytics header cards
-- ══════════════════════════════════════════════════════════════
create or replace function get_billing_analytics_summary()
returns jsonb
language plpgsql
security definer
as $$
declare
  result jsonb;
begin
  select jsonb_build_object(
    -- Total MRR (active + trialing, in INR)
    'total_mrr_inr', (
      select coalesce(sum(last_invoice_amount), 0) / 100
      from org_billing
      where subscription_status in ('active', 'trialing')
        and last_invoice_amount > 0
    ),
    -- MoM MRR growth (compare this month vs last month from snapshots)
    'mrr_growth_pct', (
      with monthly as (
        select
          date_trunc('month', snapshot_date) as month,
          sum(mrr_paise) / 100 as mrr
        from mrr_snapshots
        where status in ('active', 'trialing')
        group by date_trunc('month', snapshot_date)
        order by month desc
        limit 2
      )
      select
        case when lag(mrr) over (order by month) > 0
          then round(100.0 * (mrr - lag(mrr) over (order by month))
                     / lag(mrr) over (order by month), 1)
          else null
        end
      from monthly
      limit 1
    ),
    -- Total paying subscribers
    'paying_subscribers', (
      select count(*) from org_billing
      where subscription_status in ('active', 'trialing')
    ),
    -- Active trials (not yet converted)
    'free_trials', (
      select count(*) from organizations
      where plan = 'trial'
    ),
    -- Monthly churn rate
    'churn_rate_pct', (
      select monthly_churn_rate_pct from v_trial_conversion
    ),
    -- Trial → paid conversion rate
    'conversion_rate_pct', (
      select conversion_rate_pct from v_trial_conversion
    ),
    -- ARPA (average revenue per account) in INR
    'arpa_inr', (
      select round(avg(last_invoice_amount) / 100)
      from org_billing
      where subscription_status in ('active', 'trialing')
        and last_invoice_amount > 0
    ),
    -- Past due count (payment failures)
    'past_due_count', (
      select count(*) from org_billing
      where subscription_status = 'past_due'
    )
  ) into result;
  return result;
end;
$$;


-- ══════════════════════════════════════════════════════════════
-- FUNCTION: record_mrr_snapshot
-- Called daily by pg_cron to record MRR for charting over time
-- ══════════════════════════════════════════════════════════════
create or replace function record_mrr_snapshot()
returns void
language plpgsql
security definer
as $$
begin
  insert into mrr_snapshots (snapshot_date, org_id, plan, mrr_paise, status)
  select
    current_date,
    ob.org_id,
    o.plan,
    coalesce(ob.last_invoice_amount, 0),
    ob.subscription_status
  from org_billing ob
  join organizations o on o.id = ob.org_id
  on conflict (snapshot_date, org_id)
  do update set
    mrr_paise  = excluded.mrr_paise,
    plan       = excluded.plan,
    status     = excluded.status;
end;
$$;

