-- SOURCE: supabase/migrations/005_performance.sql
-- TrialMatch India — Performance Migration 005
-- Run AFTER 004_feasibility.sql
--
-- WHY: lib/feasibility.ts runs ILIKE '%term%' queries against diagnosis,
-- medications, labs, and comorbidities for every site × every criterion.
-- Without trigram indexes these are sequential full table scans — fine at
-- Phase 1 scale (3 pilot orgs) but will degrade as patient counts and org
-- counts grow in Phase 2 (sponsor portal, multi-site feasibility).
--
-- pg_trgm enables fast ILIKE '%substring%' lookups via GIN indexes,
-- which a standard btree index cannot accelerate.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX IF NOT EXISTS idx_patients_diagnosis_trgm
  ON patients USING gin (diagnosis gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_patients_medications_trgm
  ON patients USING gin (medications gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_patients_labs_trgm
  ON patients USING gin (labs gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_patients_comorbidities_trgm
  ON patients USING gin (comorbidities gin_trgm_ops);

-- Composite index to speed up the base "active patients at org" count
-- that feasibility.ts runs first for every site.
CREATE INDEX IF NOT EXISTS idx_patients_org_active
  ON patients (org_id, is_archived) WHERE is_archived = false;

-- Verify
SELECT indexname FROM pg_indexes
WHERE tablename = 'patients' AND indexname LIKE '%trgm%';
-- Expected: 4 rows


-- SOURCE: supabase/migrations/006_site_twin.sql
-- TrialMatch India — India Site Twin Network Migration 006
-- Run AFTER 005_performance.sql
-- Creates india_site_profiles (the Site Twin table) + org linking function

CREATE TABLE IF NOT EXISTS india_site_profiles (
  id                   uuid PRIMARY KEY DEFAULT uuid_generate_v4(),

  -- Link to a TrialMatch org IF this site has signed up (nullable until they do)
  org_id               uuid REFERENCES organizations(id) ON DELETE SET NULL,

  -- Identity
  institution_name     text NOT NULL,
  city                 text,
  state                text,
  site_type            text DEFAULT 'hospital'
    CHECK (site_type IN ('hospital','academic','cro','research_center','government')),
  specialties          text[] DEFAULT '{}',

  -- Performance metrics (refreshed weekly by cron)
  active_trials        int DEFAULT 0,
  pi_count             int DEFAULT 0,
  total_patients       int DEFAULT 0,   -- de-identified count from TrialMatch
  avg_enrollment_rate  float,           -- patients enrolled per month (historical)
  avg_dropout_rate     float,
  avg_startup_days     int,             -- contract-to-first-patient average

  -- Status
  is_partner           boolean DEFAULT false,  -- true when org_id is set
  is_verified          boolean DEFAULT false,

  -- Source tracking
  ctgov_nct_ids        text[] DEFAULT '{}',    -- NCT IDs of trials at this site
  ctri_ids             text[] DEFAULT '{}',

  created_at           timestamptz DEFAULT now(),
  updated_at           timestamptz DEFAULT now()
);

-- Prevent duplicates from seed script
CREATE UNIQUE INDEX IF NOT EXISTS idx_site_profiles_institution_city
  ON india_site_profiles (lower(institution_name), lower(coalesce(city,'')));

CREATE INDEX IF NOT EXISTS idx_site_profiles_city      ON india_site_profiles (city);
CREATE INDEX IF NOT EXISTS idx_site_profiles_state     ON india_site_profiles (state);
CREATE INDEX IF NOT EXISTS idx_site_profiles_partner   ON india_site_profiles (is_partner);
CREATE INDEX IF NOT EXISTS idx_site_profiles_org       ON india_site_profiles (org_id) WHERE org_id IS NOT NULL;

-- GIN index for specialty search (array containment)
CREATE INDEX IF NOT EXISTS idx_site_profiles_specialties
  ON india_site_profiles USING gin (specialties);

-- Full-text search on institution name
CREATE INDEX IF NOT EXISTS idx_site_profiles_name_trgm
  ON india_site_profiles USING gin (institution_name gin_trgm_ops);

-- ── link_org_to_site_twin() ────────────────────────────────────────────────
-- Called when an org signs up or admin links manually.
-- Fuzzy-matches org name to site profiles and sets org_id + is_partner = true.
CREATE OR REPLACE FUNCTION link_org_to_site_twin(p_org_id uuid)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  v_org_name text;
  v_site_id  uuid;
BEGIN
  SELECT name INTO v_org_name FROM organizations WHERE id = p_org_id;
  IF v_org_name IS NULL THEN RETURN; END IF;

  -- Try exact match first, then trigram similarity
  SELECT id INTO v_site_id
  FROM india_site_profiles
  WHERE lower(institution_name) = lower(v_org_name)
     OR similarity(institution_name, v_org_name) > 0.5
  ORDER BY similarity(institution_name, v_org_name) DESC
  LIMIT 1;

  IF v_site_id IS NOT NULL THEN
    UPDATE india_site_profiles
    SET org_id = p_org_id, is_partner = true, updated_at = now()
    WHERE id = v_site_id;
  END IF;
END;
$$;

-- ── RLS: site profiles are publicly readable (aggregate data only, no PII)
ALTER TABLE india_site_profiles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "site_profiles_read_all_authenticated"
  ON india_site_profiles FOR SELECT
  USING (auth.uid() IS NOT NULL);

-- Only service role (admin/cron) can insert/update
CREATE POLICY "site_profiles_service_write"
  ON india_site_profiles FOR ALL
  USING (auth.role() = 'service_role');

-- Verify
SELECT table_name FROM information_schema.tables
WHERE table_schema = 'public' AND table_name = 'india_site_profiles';
-- Expected: 1 row


-- SOURCE: supabase/migrations/007_site_twin_performance.sql
-- TrialMatch India — Site Twin Performance Refresh Migration 007
-- Run AFTER 006_site_twin.sql
-- Adds refresh_site_twin_performance() — called by weekly cron

-- ── refresh_site_twin_performance() ───────────────────────────────────────
-- Updates aggregate metrics for every partner site (org_id IS NOT NULL).
-- Reads only de-identified counts — never exposes patient-level data.
CREATE OR REPLACE FUNCTION refresh_site_twin_performance()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  rec RECORD;
BEGIN
  FOR rec IN
    SELECT isp.id, isp.org_id
    FROM india_site_profiles isp
    WHERE isp.org_id IS NOT NULL
  LOOP
    UPDATE india_site_profiles
    SET
      -- Active (non-archived) patient count from TrialMatch
      total_patients = (
        SELECT COUNT(*)::int
        FROM patients
        WHERE org_id = rec.org_id AND is_archived = false
      ),
      -- PI count at this org (from pi_contacts linked to their NCT IDs)
      pi_count = (
        SELECT COUNT(DISTINCT pi_name)::int
        FROM pi_contacts pc
        WHERE pc.pi_institution ILIKE
          (SELECT '%' || name || '%' FROM organizations WHERE id = rec.org_id)
      ),
      updated_at = now()
    WHERE id = rec.id;
  END LOOP;

  -- For all sites (partner + non-partner): update active_trials from
  -- the pi_contacts table which is sourced from CT.gov
  UPDATE india_site_profiles isp
  SET active_trials = sub.cnt
  FROM (
    SELECT
      lower(pi_institution) AS inst_key,
      COUNT(DISTINCT nct_id)::int AS cnt
    FROM pi_contacts
    GROUP BY lower(pi_institution)
  ) sub
  WHERE lower(isp.institution_name) = sub.inst_key;

END;
$$;

-- ── Scheduled refresh: runs every Sunday at 2 AM IST (20:30 UTC Saturday)
-- Requires pg_cron extension (already enabled in Supabase)
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    PERFORM cron.schedule(
      'site-twin-weekly-refresh',
      '30 20 * * 0',   -- Sunday 02:00 IST
      $cron$SELECT refresh_site_twin_performance();$cron$
    );
  END IF;
END $$;

-- Verify function exists
SELECT proname FROM pg_proc WHERE proname = 'refresh_site_twin_performance';
-- Expected: 1 row


-- SOURCE: supabase/migrations/008_prescreening.sql
-- TrialMatch India — Pre-screening Checklists Migration 008
