-- SOURCE: supabase/migrations/011_audit_log.sql
-- TrialMatch India — Audit Log Migration 011
-- Run AFTER 010_enrollment_monitor.sql
--
-- Implements a tamper-proof, immutable audit trail required by:
--   - India DPDP Act 2023 (data processing accountability)
--   - ICH GCP E6(R2) (clinical trial data integrity)
--   - ISO 27001 (information security)
--
-- Design principles:
--   - INSERT only — no UPDATE, no DELETE ever
--   - Every meaningful action produces a row
--   - Before/after state captured for mutations
--   - IP address + user agent for forensic reconstruction
--   - RLS: org admins can read their org's log; service role only for writes

-- ── audit_log ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS audit_log (
  id            uuid          PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id        uuid          REFERENCES organizations(id),       -- nullable for system events
  user_id       uuid          REFERENCES users(id),               -- nullable for cron/system
  session_id    text,                                             -- NextAuth session jti

  -- What happened
  action        text          NOT NULL,
  -- Core actions:
  -- auth:         login, logout, login_failed, session_expired
  -- patient:      patient_created, patient_updated, patient_archived, patient_viewed_phi
  -- match:        match_job_started, match_job_completed, match_result_viewed
  -- report:       pdf_generated, pdf_downloaded, pdf_emailed
  -- prescreening: checklist_generated, checklist_reviewed, whatsapp_sent
  -- protocol:     protocol_uploaded, protocol_parsed, protocol_updated, protocol_archived
  -- feasibility:  feasibility_run, feasibility_result_exported
  -- engagement:   engagement_initiated, engagement_notified, engagement_responded, engagement_closed
  -- consent:      consent_recorded, consent_withdrawn, dpdp_request_processed
  -- team:         user_invited, user_role_changed, user_deactivated
  -- billing:      plan_changed, payment_processed, payment_failed
  -- data:         data_export, bulk_import, data_retention_applied
  -- security:     api_key_created, api_key_revoked, mfa_enabled, suspicious_access
  -- ai:           ai_match_called, ai_prescreening_called, ai_protocol_parsed, ai_monitor_alert

  -- What was affected
  entity_type   text,                    -- 'patient' | 'match_result' | 'protocol' | etc.
  entity_id     text,                    -- UUID of the affected record

  -- State capture (JSONB — only for mutations, nil for read events)
  before_state  jsonb,                   -- state before mutation (redacted of raw PII)
  after_state   jsonb,                   -- state after mutation (redacted of raw PII)

  -- Request context
  ip_address    inet,
  user_agent    text,
  request_id    text,                    -- X-Request-ID header for tracing

  -- Outcome
  outcome       text          DEFAULT 'success'
    CHECK (outcome IN ('success', 'failure', 'partial')),
  error_code    text,                    -- only when outcome = 'failure'
  error_message text,

  -- Metadata
  metadata      jsonb         DEFAULT '{}',  -- extra context (e.g. trial NCT IDs, counts)

  -- Immutable timestamp — stored as timestamptz WITH time zone
  created_at    timestamptz   DEFAULT now() NOT NULL,

  -- Prevent accidental updates
  CONSTRAINT audit_log_no_update CHECK (created_at IS NOT NULL)
);

-- Performance indexes
--
-- REAL BUG FOUND AND FIXED HERE, by actually running this file against a
-- real fresh Postgres database rather than assuming it: schema.sql
-- ALWAYS creates a minimal audit_log first (see migration 016's header
-- comment for the full story), so the CREATE TABLE IF NOT EXISTS above
-- is always a silent no-op — audit_log never actually gets the columns
-- this file defines. The idx_audit_entity index below used to reference
-- entity_type, a column that (until migration 016 adds it) does not
-- exist on the table that's actually there. That's not a silent skip —
-- it's a hard SQL error that aborts this entire script, in one paste,
-- before a single line below this point ever runs: no RLS on audit_log,
-- neither policy, neither no-delete/no-update rule, no
-- org_audit_summary view, and no consent_records table — the DPDP Act
-- §6 consent-tracking table this same file defines further down. Every
-- one of those gaps is completed correctly in migration 025, once the
-- entity_type column actually exists. This index is intentionally
-- removed from here (not just left to fail) so a fresh deploy runs
-- 001 → 024 without a hard stop; migration 016 creates the equivalent
-- index once the column that's queried actually exists.
CREATE INDEX IF NOT EXISTS idx_audit_org_time    ON audit_log (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_user_time   ON audit_log (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_action      ON audit_log (action, created_at DESC);

-- ── RLS: strict access control ────────────────────────────────────────────
ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;

-- Org admins can read their own org's audit log
CREATE POLICY "org_admins_read_audit"
  ON audit_log FOR SELECT
  USING (
    org_id = (
      SELECT org_id FROM users
      WHERE id = auth.uid() AND role IN ('admin', 'owner')
    )
    OR auth.role() = 'service_role'
  );

-- Only service_role (server-side code) can INSERT
CREATE POLICY "service_role_insert_audit"
  ON audit_log FOR INSERT
  WITH CHECK (auth.role() = 'service_role');

-- CRITICAL: NO UPDATE, NO DELETE policies — these are intentionally absent
-- Any attempt to UPDATE or DELETE audit records returns a policy violation error

-- ── Prevent row deletion at DB level (belt + suspenders) ─────────────────
CREATE OR REPLACE RULE no_delete_audit AS ON DELETE TO audit_log
  DO INSTEAD NOTHING;

CREATE OR REPLACE RULE no_update_audit AS ON UPDATE TO audit_log
  DO INSTEAD NOTHING;

-- ── Helper view: recent activity per org (last 90 days) ──────────────────
--
-- REMOVED FROM HERE — same class of bug as the index above: this SELECTs
-- `outcome`, another column that (until migration 016 adds it) doesn't
-- exist on the table schema.sql actually created, so this CREATE VIEW
-- was ALSO a hard error that aborted the rest of this script — meaning
-- consent_records below never got created either, on a fresh deploy.
-- Migration 021 already independently recreates this exact view once
-- the column exists; that's the real, working definition. Confirmed by
-- actually running this file against a fresh Postgres database, not
-- assumed.

-- ── consent_records (DPDP Act 2023 §6 — explicit consent tracking) ───────
-- Separate from audit_log — consent records need even stricter guarantees
CREATE TABLE IF NOT EXISTS consent_records (
  id              uuid        PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id          uuid        REFERENCES organizations(id) NOT NULL,
  patient_id      uuid        REFERENCES patients(id),

  -- Consent specifics
  consent_type    text        NOT NULL
    CHECK (consent_type IN (
      'data_processing',       -- basic TrialMatch processing
      'trial_matching',        -- AI-based trial matching
      'sponsor_aggregate',     -- sharing aggregate data with sponsors
      'pdf_report',            -- PDF report generation
      'whatsapp_notification', -- WhatsApp messages
      'third_party_sharing',   -- any third-party data share
      'data_retention'         -- explicit retention period acknowledgement
    )),
  version         text        NOT NULL,    -- consent form version (e.g. '2024.1')
  given           boolean     NOT NULL,    -- true = consented, false = withdrawn
  given_at        timestamptz,
  withdrawn_at    timestamptz,

  -- How was consent collected?
  collection_method text      NOT NULL
    CHECK (collection_method IN ('verbal_logged', 'written_form', 'digital_form', 'abdm_derived')),
  collected_by    uuid        REFERENCES users(id),

  -- Evidence
  notes           text,
  evidence_ref    text,       -- e.g. signed form file name / ABHA consent artefact ID

  created_at      timestamptz DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_consent_patient  ON consent_records (patient_id, consent_type);
CREATE INDEX IF NOT EXISTS idx_consent_org      ON consent_records (org_id, given);

ALTER TABLE consent_records ENABLE ROW LEVEL SECURITY;

CREATE POLICY "org_isolation_consent"
  ON consent_records
  USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));

-- Verify
SELECT table_name FROM information_schema.tables
WHERE table_schema = 'public'
  AND table_name IN ('audit_log', 'consent_records')
ORDER BY table_name;
-- Expected: 2 rows


-- SOURCE: supabase/migrations/012_match_accuracy.sql
-- TrialMatch India — Match Accuracy Tracking Migration 012
-- Closes Phase 1 gap: "match accuracy stats start accumulating"
-- Links screen_fail_reason to specific trial criteria for continuous improvement

CREATE TABLE IF NOT EXISTS match_accuracy_events (
  id               uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id           uuid REFERENCES organizations(id) ON DELETE CASCADE,
  match_result_id  uuid REFERENCES match_results(id) ON DELETE CASCADE,
  patient_id       uuid REFERENCES patients(id) ON DELETE CASCADE,
  nct_id           text NOT NULL,

  -- What happened
  outcome          text NOT NULL
    CHECK (outcome IN ('enrolled','screen_failed','patient_declined','trial_closed')),
  screen_fail_reason text,

  -- Which criteria were marked as 'partial' or 'unmet' in the original match
  -- Array of { criterion, match_status: 'met'|'partial'|'unmet', field }
  criteria_at_match jsonb DEFAULT '[]',

  -- Did the screen failure align with a partial/unmet criterion? (set by nightly job)
  failure_predicted boolean,
  failure_criterion text,     -- the criterion that predicted failure (if any)

  created_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_accuracy_org     ON match_accuracy_events (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_accuracy_nct     ON match_accuracy_events (nct_id);
CREATE INDEX IF NOT EXISTS idx_accuracy_outcome ON match_accuracy_events (outcome);

ALTER TABLE match_accuracy_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "org_isolation_accuracy" ON match_accuracy_events
  USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));

-- View: criterion-level screen failure rates (powers match accuracy improvement)
CREATE OR REPLACE VIEW v_criterion_failure_rates AS
SELECT
  nct_id,
  failure_criterion,
  COUNT(*) FILTER (WHERE outcome = 'screen_failed')  AS screen_fail_count,
  COUNT(*) FILTER (WHERE outcome = 'enrolled')        AS enrolled_count,
  COUNT(*)                                            AS total_outcomes,
  ROUND(
    100.0 * COUNT(*) FILTER (WHERE outcome = 'screen_failed')
    / NULLIF(COUNT(*), 0), 1
  ) AS screen_fail_rate_pct
FROM match_accuracy_events
WHERE failure_criterion IS NOT NULL
GROUP BY nct_id, failure_criterion
ORDER BY screen_fail_rate_pct DESC;

-- Trigger: auto-create accuracy event when enrollment_status changes to a terminal state
CREATE OR REPLACE FUNCTION record_match_accuracy_event()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.enrollment_status IN ('enrolled','screen_failed','patient_declined','trial_closed')
     AND (OLD.enrollment_status IS DISTINCT FROM NEW.enrollment_status) THEN
    INSERT INTO match_accuracy_events (
      org_id, match_result_id, patient_id, nct_id, outcome,
      screen_fail_reason, criteria_at_match
    )
    SELECT
      NEW.org_id,
      NEW.id,
      NEW.patient_id,
      COALESCE(NEW.matches->0->>'nctId', ''),
      NEW.enrollment_status,
      NEW.screen_fail_reason,
      COALESCE(
        (SELECT jsonb_agg(jsonb_build_object(
          'criterion', elem->>'criterion',
          'status',    elem->>'status',
          'detail',    elem->>'detail'
        ))
        FROM jsonb_array_elements(NEW.matches->0->'eligibilityDetails') AS elem),
        '[]'::jsonb
      )
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_match_accuracy ON match_results;
CREATE TRIGGER trg_match_accuracy
  AFTER UPDATE OF enrollment_status ON match_results
  FOR EACH ROW EXECUTE FUNCTION record_match_accuracy_event();

SELECT 'Migration 012 complete' AS status;


-- SOURCE: supabase/migrations/013_fixes.sql
-- TrialMatch India — Critical Bug Fixes Migration 013
-- Run AFTER 012_match_accuracy.sql
--
-- Fix 1: Site twin upsert was broken because the unique INDEX used lower()
--         expressions but Supabase upsert onConflict needs a named CONSTRAINT.
--         Add the named constraint and a helper RPC for the seed script.
--
-- Fix 2: Enrollment monitor tasks were never created automatically.
--         Add a DB-level trigger as a safety net (match/index.ts also inserts,
--         but this trigger ensures tasks are created even from future code paths).

-- ═══════════════════════════════════════════════════════════════════
-- FIX 1: Named unique constraint on india_site_profiles
-- ═══════════════════════════════════════════════════════════════════

-- Drop the existing expression index (can't convert to constraint directly)
DROP INDEX IF EXISTS idx_site_profiles_institution_city;

-- Add proper named UNIQUE CONSTRAINT that the seed upsert can reference
-- PostgreSQL doesn't support expression-based UNIQUE CONSTRAINTs directly,
-- so we use a generated column approach for clean upserts.

ALTER TABLE india_site_profiles
  ADD COLUMN IF NOT EXISTS institution_city_key text
  GENERATED ALWAYS AS (lower(institution_name) || '|' || lower(coalesce(city, ''))) STORED;

CREATE UNIQUE INDEX IF NOT EXISTS idx_site_profiles_key
  ON india_site_profiles (institution_city_key);

-- Upsert RPC used by seed-site-twins.ts
-- Returns the upserted row ID.
CREATE OR REPLACE FUNCTION upsert_site_profile(
  p_institution_name  text,
  p_city              text,
  p_state             text,
  p_site_type         text,
  p_specialties       text[],
  p_ctgov_nct_ids     text[],
  p_ctri_ids          text[],
  p_active_trials     int
) RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE
  v_id  uuid;
BEGIN
  -- institution_city_key is GENERATED ALWAYS AS (...) STORED (see the
  -- ALTER TABLE above) — Postgres computes it automatically from
  -- institution_name/city and never accepts an explicit value for it in
  -- an INSERT, on any deployment. An earlier version of this function
  -- tried to insert one anyway (a leftover from before the column became
  -- generated), which made this RPC fail on every call — confirmed by
  -- actually running it against a real Postgres instance, not just
  -- reading the SQL. It's omitted here entirely; ON CONFLICT
  -- (institution_city_key) below still works, since Postgres computes the
  -- generated value before conflict detection regardless of whether the
  -- INSERT mentions it.
  INSERT INTO india_site_profiles (
    institution_name, city, state, site_type, specialties,
    ctgov_nct_ids, ctri_ids, active_trials
  ) VALUES (
    p_institution_name, p_city, p_state, p_site_type, p_specialties,
    p_ctgov_nct_ids, p_ctri_ids, p_active_trials
  )
  ON CONFLICT (institution_city_key) DO UPDATE SET
    specialties     = CASE
      WHEN array_length(EXCLUDED.specialties, 1) > array_length(india_site_profiles.specialties, 1)
      THEN EXCLUDED.specialties
      ELSE india_site_profiles.specialties
    END,
    ctgov_nct_ids   = (
      SELECT array_agg(DISTINCT e) FROM unnest(
        india_site_profiles.ctgov_nct_ids || EXCLUDED.ctgov_nct_ids
      ) AS e
    ),
    ctri_ids        = (
      SELECT array_agg(DISTINCT e) FROM unnest(
        india_site_profiles.ctri_ids || EXCLUDED.ctri_ids
      ) AS e
    ),
    active_trials   = GREATEST(india_site_profiles.active_trials, EXCLUDED.active_trials),
    updated_at      = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

GRANT EXECUTE ON FUNCTION upsert_site_profile TO service_role;

-- ═══════════════════════════════════════════════════════════════════
-- FIX 2: Auto-create enrollment monitor tasks via DB trigger
-- This is a safety net — match/index.ts also inserts tasks directly.
-- The trigger catches any future code paths that update match_results
-- to 'done' without going through match/index.ts (e.g. future FHIR jobs).
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION create_enrollment_monitor_task()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  v_nct_id text;
BEGIN
  -- Only fire when status transitions TO 'done' from something else
  IF NEW.status = 'done' AND (OLD.status IS DISTINCT FROM 'done') THEN
    -- Extract top match NCT ID from the matches JSONB array
    v_nct_id := NEW.matches->0->>'nctId';

    -- Insert monitor task; ignore if one already exists for this match result
    INSERT INTO enrollment_monitor_tasks (
      org_id,
      match_result_id,
      patient_id,
      nct_id,
      enrollment_status,
      last_status_change,
      days_in_status,
      alert_if_no_contact_hours,
      alert_on_competing_trial,
      alert_count,
      is_active
    ) VALUES (
      NEW.org_id,
      NEW.id,
      NEW.patient_id,
      v_nct_id,
      COALESCE(NEW.enrollment_status, 'pending'),
      now(),
      0,
      48,
      true,
      0,
      true
    )
    ON CONFLICT (match_result_id) DO NOTHING;
  END IF;

  -- Keep monitor task in sync when enrollment_status changes
  IF NEW.enrollment_status IS DISTINCT FROM OLD.enrollment_status THEN
    UPDATE enrollment_monitor_tasks
    SET
      enrollment_status  = NEW.enrollment_status,
      last_status_change = now(),
      days_in_status     = 0,
      -- Mark as inactive when pipeline reaches a terminal state
      is_active          = CASE
        WHEN NEW.enrollment_status IN ('enrolled', 'screen_failed', 'patient_declined', 'trial_closed')
        THEN false
        ELSE true
      END,
      completed_at       = CASE
        WHEN NEW.enrollment_status IN ('enrolled', 'screen_failed', 'patient_declined', 'trial_closed')
        THEN now()
        ELSE NULL
      END
    WHERE match_result_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$$;

-- Unique constraint on match_result_id so ON CONFLICT DO NOTHING works.
--
-- `ADD CONSTRAINT IF NOT EXISTS` (the previous version of this
-- statement) is not valid PostgreSQL syntax — IF NOT EXISTS is only
-- supported for ADD COLUMN, not ADD CONSTRAINT. It failed as a syntax
-- error every time this migration ran, which silently meant this
-- constraint was NEVER created — confirmed by actually running this
-- migration against a real Postgres instance and then exercising the
-- trigger below for real: every UPDATE of match_results to status='done'
-- (i.e. every completed match, in production) threw "there is no unique
-- or exclusion constraint matching the ON CONFLICT specification" from
-- inside this trigger, which aborted that UPDATE — the core match flow's
-- own result could never actually get persisted. This DO block achieves
-- the same "safe to re-run" intent the invalid IF NOT EXISTS syntax was
-- reaching for, correctly this time.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'enrollment_monitor_tasks_match_result_id_key'
  ) THEN
    ALTER TABLE enrollment_monitor_tasks
      ADD CONSTRAINT enrollment_monitor_tasks_match_result_id_key
      UNIQUE (match_result_id);
  END IF;
END $$;

DROP TRIGGER IF EXISTS trg_enrollment_monitor ON match_results;
CREATE TRIGGER trg_enrollment_monitor
  AFTER UPDATE ON match_results
  FOR EACH ROW
  EXECUTE FUNCTION create_enrollment_monitor_task();

-- Backfill: create tasks for existing completed match results that have none
INSERT INTO enrollment_monitor_tasks (
  org_id, match_result_id, patient_id, nct_id,
  enrollment_status, last_status_change, days_in_status,
  alert_if_no_contact_hours, alert_on_competing_trial, alert_count, is_active
)
SELECT
  mr.org_id,
  mr.id,
  mr.patient_id,
  mr.matches->0->>'nctId',
  COALESCE(mr.enrollment_status, 'pending'),
  COALESCE(mr.updated_at, mr.created_at),
  0, 48, true, 0,
  mr.enrollment_status NOT IN ('enrolled', 'screen_failed', 'patient_declined', 'trial_closed')
FROM match_results mr
LEFT JOIN enrollment_monitor_tasks emt ON emt.match_result_id = mr.id
WHERE mr.status = 'done' AND emt.id IS NULL
ON CONFLICT (match_result_id) DO NOTHING;

SELECT
  (SELECT COUNT(*) FROM india_site_profiles)    AS site_profiles,
  (SELECT COUNT(*) FROM enrollment_monitor_tasks) AS monitor_tasks;
-- Both should show row counts after backfill (not zeros).


-- SOURCE: supabase/migrations/014_security_fixes.sql
-- TrialMatch India — Security & Correctness Fixes Migration 014
-- Run AFTER 013_fixes.sql
--
-- Fix 1: rematch_runs was the only table (of 25) created without RLS
--         enabled. Low severity — it holds only aggregate job counts, no
--         patient or org data — but closed here for completeness. No
--         policies are added because only the cron job (via the
--         service-role client, which bypasses RLS entirely) ever touches
--         this table; enabling RLS with zero policies means anon/
--         authenticated roles get zero access by default, which is correct.
--
-- Fix 2: match_results needs a source_status column. This supports the
--         lib/matcher.ts fix that removed the "AI-Synthesised" fabricated-
--         trial fallback — every match run now records whether
--         ClinicalTrials.gov and CTRI were actually reachable, so the UI
--         can show a coordinator the honest difference between "zero live
--         trials found" and "we couldn't check right now" instead of
--         collapsing both into the same silent empty state.

-- ═══════════════════════════════════════════════════════════════════
-- FIX 1: Enable RLS on rematch_runs
-- ═══════════════════════════════════════════════════════════════════

alter table rematch_runs enable row level security;

-- ═══════════════════════════════════════════════════════════════════
-- FIX 2: source_status column on match_results
-- ═══════════════════════════════════════════════════════════════════

alter table match_results
  add column if not exists source_status jsonb;

comment on column match_results.source_status is
  'Per-source fetch outcome for this match run, e.g. {"ctgov":"ok","ctri":"error","ctriError":"..."}. '
  '''error'' means the registry could not be reached — distinct from a genuine zero-result search. '
  'Written by lib/matcher.ts. Added in migration 014 alongside removal of the AI-Synthesised fabricated-trial fallback.';

-- Sanity check — should show the new column present with zero NOT NULL
-- violations (it's nullable, so existing rows are unaffected).
SELECT column_name, is_nullable, data_type
FROM information_schema.columns
WHERE table_name = 'match_results' AND column_name = 'source_status';


-- SOURCE: supabase/migrations/015_fidelius_keys.sql
-- TrialMatch India — Migration 015
-- Run AFTER 014_security_fixes.sql
--
-- Adds columns to store the ephemeral Fidelius (ABDM ECDH) key material
-- generated per session in lib/abdm-client.ts's requestHealthInfo(). This
-- is required for the real decryption implemented in lib/fidelius.ts —
-- decrypting the HIP's callback needs OUR private key and nonce again,
-- which must be persisted somewhere between the request and the callback.
--
-- Previously there was no such storage because the old ECDH implementation
-- was a placeholder that didn't do real key exchange at all.
--
-- These columns hold key material scoped to a single, short-lived
-- (10-minute expiry per abdm_sessions.expires_at) ABDM consent session —
-- not a long-term credential. Still sensitive: RLS on abdm_sessions
-- (already enabled in schema.sql) restricts read access to users in the
-- same org.

alter table abdm_sessions
  add column if not exists fidelius_private_key text,
  add column if not exists fidelius_public_key_x509 text,
  add column if not exists fidelius_nonce text;

comment on column abdm_sessions.fidelius_private_key is
  'Base64 ephemeral Curve25519 private key generated for this session (lib/fidelius.ts). '
  'Never reused across sessions. Needed to decrypt the HIP''s callback response.';
comment on column abdm_sessions.fidelius_public_key_x509 is
  'Base64 X.509-wrapped public key sent to ABDM in the health-information request. '
  'Stored for audit/debugging; not needed for decryption (only the private key + nonce are).';
comment on column abdm_sessions.fidelius_nonce is
  'Base64, 32 random bytes generated for this session. Combined with the HIP''s own '
  'nonce (from the callback payload) to derive the AES-GCM salt/IV — see lib/fidelius.ts.';

-- Sanity check
SELECT column_name, is_nullable, data_type
FROM information_schema.columns
WHERE table_name = 'abdm_sessions' AND column_name LIKE 'fidelius_%';


-- SOURCE: supabase/migrations/016_audit_log_columns_fix.sql
-- TrialMatch India — Migration 016
-- Run AFTER 015_fidelius_keys.sql
--
-- Fixes a severe, deterministic bug in 011_audit_log.sql: it declares
-- `CREATE TABLE IF NOT EXISTS audit_log (...)` with a rich forensic schema
-- (session_id, entity_type, before_state, after_state, ip_address, outcome,
-- etc.) — but schema.sql ALWAYS creates a minimal 8-column audit_log first
-- (id, org_id, user_id, action, entity, entity_id, metadata, created_at),
-- and schema.sql always runs before 011 in the documented deploy order.
-- `IF NOT EXISTS` means 011's richer CREATE TABLE silently does nothing —
-- on every deployment, not just existing ones.
--
-- lib/audit.ts — the real, currently-running application code that logs
-- every meaningful action platform-wide (patient creation, matches, PDF
-- generation, consent, billing, everything) — inserts into session_id,
-- entity_type, before_state, after_state, ip_address, and outcome on every
-- single call. None of those columns exist on the real table. Since
-- lib/audit.ts writes are fire-and-forget (by design — audit failures
-- shouldn't block real actions), this fails completely silently: every
-- audit_log insert has been erroring, console.error'd, and discarded. The
-- audit trail this project's own migration comments describe as required
-- for DPDP Act 2023 / ICH GCP E6(R2) / ISO 27001 has effectively been
-- empty since 011 was written.
--
-- Fix: ALTER TABLE ADD COLUMN IF NOT EXISTS for every column lib/audit.ts
-- actually writes to, rather than a CREATE TABLE that can silently no-op.
-- Non-destructive — the existing `entity` column (schema.sql's original,
-- narrower field) is left in place rather than dropped; entity_type is
-- added as the new column the application actually uses.

ALTER TABLE audit_log
  ADD COLUMN IF NOT EXISTS session_id    text,
  ADD COLUMN IF NOT EXISTS entity_type   text,
  ADD COLUMN IF NOT EXISTS before_state  jsonb,
  ADD COLUMN IF NOT EXISTS after_state   jsonb,
  ADD COLUMN IF NOT EXISTS ip_address    inet,
  ADD COLUMN IF NOT EXISTS user_agent    text,
  ADD COLUMN IF NOT EXISTS request_id    text,
  ADD COLUMN IF NOT EXISTS outcome       text DEFAULT 'success',
  ADD COLUMN IF NOT EXISTS error_code    text,
  ADD COLUMN IF NOT EXISTS error_message text;

-- Re-add the CHECK constraint on outcome (can't be part of ADD COLUMN
-- when the column already has rows, but audit_log is either empty or was
-- only ever populated by schema.sql's pre-011 code path, which never set
-- outcome — so backfill existing rows to the default before constraining).
UPDATE audit_log SET outcome = 'success' WHERE outcome IS NULL;

ALTER TABLE audit_log
  DROP CONSTRAINT IF EXISTS audit_log_outcome_check;
ALTER TABLE audit_log
  ADD CONSTRAINT audit_log_outcome_check CHECK (outcome IN ('success', 'failure', 'partial'));

-- The index 011 intended on entity_type/entity_id — also silently never
-- created for the same reason (CREATE INDEX IF NOT EXISTS referencing a
-- column that, until the ALTER above, didn't exist would itself have
-- errored and been skipped by the same deploy run).
CREATE INDEX IF NOT EXISTS idx_audit_entity_type ON audit_log (entity_type, entity_id);

-- Sanity check — confirms every column lib/audit.ts writes to now exists.
SELECT column_name, data_type
FROM information_schema.columns
WHERE table_name = 'audit_log'
  AND column_name IN (
    'session_id','entity_type','entity_id','before_state','after_state',
    'ip_address','user_agent','request_id','outcome','error_code','error_message'
  )
ORDER BY column_name;
-- Expected: 11 rows. If fewer, something above did not apply.


-- SOURCE: supabase/migrations/017_structured_clinical_data.sql
-- TrialMatch India — Migration 017
-- Run AFTER 016_audit_log_columns_fix.sql
--
-- Structured Clinical Data Model — Phase 1 (additive)
--
-- Why: lib/matcher.ts currently sends the patient record to Claude as
-- prose (`Labs:HbA1c 9.2%, eGFR 68`) and asks the model to judge every
-- criterion — including purely arithmetic ones like "age >= 18" or
-- "eGFR >= 45 mL/min" that don't need a language model at all. That's
-- the same structural gap that let a fetch failure get silently answered
-- with a fabricated trial (see 014's comments) — there's no deterministic
-- floor underneath the LLM anywhere in this pipeline. Structured data is
-- the prerequisite for building one: you cannot evaluate `lab_value >=
-- threshold` in code if the lab value lives inside a free-text sentence.
--
-- What this migration does NOT do: touch the existing patients.labs /
-- .medications / .biomarkers / .comorbidities / .allergies text columns,
-- change how lib/matcher.ts builds its prompt, or build the rule
-- evaluator itself. This is schema only — additive, alongside the
-- existing free-text fields, per this project's own established migration
-- philosophy (013compare, 014, 015, 016 all add rather than replace).
-- The matcher, the intake form, and the deterministic evaluator are
-- separate, subsequent pieces of work that consume this schema once it
-- exists; building all of it in one migration would be exactly the "big
-- bang" this project has consistently avoided elsewhere.
--
-- Scope: five entities, chosen because they cover the actual recurring
-- criterion shapes seen in this project's own trial data (see the
-- Section 3 eligibility breakdowns in clinical_trial_match_report_template.pdf
-- and the example trials in lib/matcher.ts's own prompt): lab thresholds,
-- medication status/duration, biomarker results, comorbidity flags, and
-- allergy exclusions. Deliberately NOT included: imaging, procedures,
-- vital signs as separate tables — nothing in this codebase's actual
-- matching logic references them yet, and adding them now would be
-- speculative structure with no consumer, which is its own kind of
-- over-engineering.
--
-- diagnosis/stage remain top-level columns on patients (not split out) —
-- the product currently models one primary diagnosis per patient, and
-- there's no evidence of a need for a multi-diagnosis timeline yet.
-- prior_treatments is intentionally NOT a separate table: a "prior
-- treatment" and a "medication with status=discontinued" are the same
-- fact. Two overlapping free-text fields for one concept was itself a
-- modeling smell in the original design; patient_medications.status
-- covers both without duplicating the entity.

-- ═══════════════════════════════════════════════════════════════════
-- patient_labs
-- ═══════════════════════════════════════════════════════════════════
-- One row per lab result. A patient accumulates these over time — the
-- matcher should use the most recent value per test_name when evaluating
-- a criterion, which is a query concern, not a schema concern (no "is
-- current" flag needed here, unlike medications below where currency
-- is the fact itself, not derived from recency).

CREATE TABLE IF NOT EXISTS patient_labs (
  id              uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id          uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  patient_id      uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE,

  test_name       text NOT NULL,            -- e.g. 'HbA1c', 'eGFR', 'Creatinine' — free text for now,
                                             -- test_code below is the path to a controlled vocabulary later
  test_code       text,                     -- LOINC code, nullable — lib/fhir.ts's LOINC_MAP already maps
                                             -- a subset of these; this column is where that mapping lands
                                             -- when a lab result is structured, instead of staying implicit
  value_numeric   numeric,                  -- for comparable results: 'eGFR >= 45' needs this, not a string
  value_text      text,                     -- for non-numeric results: 'Positive', 'Detected', a free-text
                                             -- qualifier — never populate both value_numeric and value_text
                                             -- for a quantitative test; use whichever fits the actual result
  unit            text,                     -- 'mL/min', '%', 'mg/dL' — required for value_numeric to mean anything
  reference_range text,                     -- lab-provided normal range, as reported — for display, not evaluation
  collected_date  date,
  source          text DEFAULT 'manual' CHECK (source IN ('manual','fhir','abdm','hms_import')),
  created_by      uuid REFERENCES users(id),
  created_at      timestamptz DEFAULT now(),

  -- A test must report at least one kind of value.
  CONSTRAINT patient_labs_has_value CHECK (value_numeric IS NOT NULL OR value_text IS NOT NULL)
);

-- ═══════════════════════════════════════════════════════════════════
-- patient_medications
-- ═══════════════════════════════════════════════════════════════════
-- Covers both "current medications" and "prior treatments" from the old
-- free-text fields — status is the distinguishing fact, not two separate
-- entities. "On stable Metformin dose >=1500mg/day for >=3 months" and
-- "No prior GLP-1 agonist use" are both queries against this one table.

CREATE TABLE IF NOT EXISTS patient_medications (
  id              uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id          uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  patient_id      uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE,

  name            text NOT NULL,            -- 'Metformin' — generic name where known
  dose            text,                     -- '500mg' — kept as text; fully structuring dose+unit+route is
                                             -- a rabbit hole with no current consumer (see migration comment above)
  frequency       text,                     -- 'twice daily', 'once weekly'
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','discontinued','unknown')),
  start_date      date,
  end_date        date,                     -- null while status = 'active'
  source          text DEFAULT 'manual' CHECK (source IN ('manual','fhir','abdm','hms_import')),
  created_by      uuid REFERENCES users(id),
  created_at      timestamptz DEFAULT now(),

  CONSTRAINT patient_medications_end_after_start
    CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);

-- ═══════════════════════════════════════════════════════════════════
-- patient_biomarkers
-- ═══════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS patient_biomarkers (
  id              uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id          uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  patient_id      uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE,

  marker          text NOT NULL,            -- 'EGFR', 'PD-L1', 'BRCA1'
  status          text NOT NULL DEFAULT 'unknown' CHECK (status IN ('positive','negative','unknown','not_tested')),
  value           text,                     -- '30%', 'Exon 19 deletion' — free text, the specific finding
  tested_date     date,
  source          text DEFAULT 'manual' CHECK (source IN ('manual','fhir','abdm','hms_import')),
  created_by      uuid REFERENCES users(id),
  created_at      timestamptz DEFAULT now()
);

-- ═══════════════════════════════════════════════════════════════════
-- patient_comorbidities
-- ═══════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS patient_comorbidities (
  id              uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id          uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  patient_id      uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE,

  condition       text NOT NULL,            -- 'Hypertension', 'Dyslipidaemia'
  icd10_code      text,                     -- nullable — controlled-vocabulary path, same idea as test_code above
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','resolved','unknown')),
  diagnosed_date  date,
  source          text DEFAULT 'manual' CHECK (source IN ('manual','fhir','abdm','hms_import')),
  created_by      uuid REFERENCES users(id),
  created_at      timestamptz DEFAULT now()
);

-- ═══════════════════════════════════════════════════════════════════
-- patient_allergies
-- ═══════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS patient_allergies (
  id              uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id          uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  patient_id      uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE,

  substance       text NOT NULL,            -- 'Sulfa drugs'
  reaction        text,                     -- 'Rash', 'Anaphylaxis' — nullable, often not recorded
  severity        text DEFAULT 'unknown' CHECK (severity IN ('mild','moderate','severe','unknown')),
  source          text DEFAULT 'manual' CHECK (source IN ('manual','fhir','abdm','hms_import')),
  created_by      uuid REFERENCES users(id),
  created_at      timestamptz DEFAULT now()
);

-- ═══════════════════════════════════════════════════════════════════
-- Small, cheap, unrelated-but-related fix: patients.ecog_status already
-- has a matching closed-set TypeScript type (EcogStatus, in
-- lib/types/domain.ts) but the DB column has never had a CHECK enforcing
-- it, and the intake form renders it as a free-text <input>, not a
-- dropdown — so despite the type existing, nothing has ever enforced it.
-- Adding the constraint now; the intake form dropdown is a UI-layer
-- follow-up, not a schema one.
-- ═══════════════════════════════════════════════════════════════════

ALTER TABLE patients
  DROP CONSTRAINT IF EXISTS patients_ecog_status_check;
ALTER TABLE patients
  ADD CONSTRAINT patients_ecog_status_check
  CHECK (ecog_status IS NULL OR ecog_status IN ('ECOG 0','ECOG 1','ECOG 2','ECOG 3','ECOG 4','ECOG 5'));

-- ═══════════════════════════════════════════════════════════════════
-- Indexes — matching the query patterns a rule engine will actually run:
-- "give me this patient's labs/meds/biomarkers/comorbidities/allergies",
-- and "find the most recent value for test X on patient Y".
-- ═══════════════════════════════════════════════════════════════════

CREATE INDEX IF NOT EXISTS idx_patient_labs_patient        ON patient_labs (patient_id, test_name, collected_date DESC);
CREATE INDEX IF NOT EXISTS idx_patient_labs_org             ON patient_labs (org_id);
CREATE INDEX IF NOT EXISTS idx_patient_medications_patient  ON patient_medications (patient_id, status);
CREATE INDEX IF NOT EXISTS idx_patient_medications_org      ON patient_medications (org_id);
CREATE INDEX IF NOT EXISTS idx_patient_biomarkers_patient   ON patient_biomarkers (patient_id, marker);
CREATE INDEX IF NOT EXISTS idx_patient_biomarkers_org       ON patient_biomarkers (org_id);
CREATE INDEX IF NOT EXISTS idx_patient_comorbidities_patient ON patient_comorbidities (patient_id, status);
CREATE INDEX IF NOT EXISTS idx_patient_comorbidities_org    ON patient_comorbidities (org_id);
CREATE INDEX IF NOT EXISTS idx_patient_allergies_patient    ON patient_allergies (patient_id);
CREATE INDEX IF NOT EXISTS idx_patient_allergies_org        ON patient_allergies (org_id);

-- ═══════════════════════════════════════════════════════════════════
-- RLS — identical pattern to every other org-scoped child table in this
-- schema (patients, match_results, etc.): denormalized org_id, same
-- policy shape. No new pattern introduced.
-- ═══════════════════════════════════════════════════════════════════

ALTER TABLE patient_labs          ENABLE ROW LEVEL SECURITY;
ALTER TABLE patient_medications   ENABLE ROW LEVEL SECURITY;
ALTER TABLE patient_biomarkers    ENABLE ROW LEVEL SECURITY;
ALTER TABLE patient_comorbidities ENABLE ROW LEVEL SECURITY;
ALTER TABLE patient_allergies     ENABLE ROW LEVEL SECURITY;

CREATE POLICY "org_isolation_patient_labs"          ON patient_labs          USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));
CREATE POLICY "org_isolation_patient_medications"   ON patient_medications   USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));
CREATE POLICY "org_isolation_patient_biomarkers"    ON patient_biomarkers    USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));
CREATE POLICY "org_isolation_patient_comorbidities" ON patient_comorbidities USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));
CREATE POLICY "org_isolation_patient_allergies"     ON patient_allergies     USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));

-- Sanity check — 5 new tables, all with RLS enabled, no exceptions.
SELECT t.table_name, pt.rowsecurity
FROM information_schema.tables t
JOIN pg_tables pt ON pt.tablename = t.table_name
WHERE t.table_name IN (
  'patient_labs','patient_medications','patient_biomarkers',
  'patient_comorbidities','patient_allergies'
)
ORDER BY t.table_name;
-- Expected: 5 rows, rowsecurity = true for all.


-- SOURCE: supabase/migrations/018_trial_criteria_cache.sql
-- TrialMatch India — Migration 018
-- Run AFTER 017_structured_clinical_data.sql
--
-- Trial Criteria Cache
--
-- Why: every single match run re-extracts criteria from scratch for
-- every retrieved trial — the free rule-based regex/dictionary pass
-- (lib/rule-based-extraction.ts) AND the Claude call that extracts
-- structured criteria from whatever residual text the rule-based pass
-- couldn't parse (lib/matcher.ts's scoreWithClaude). A trial's
-- eligibility criteria do not depend on which patient is being matched
-- against it — a popular trial matched against 50 patients this week
-- pays for the same extraction 50 times over, including 50 separate
-- Claude API calls for the residual-extraction portion, purely because
-- nothing remembers the answer from the first time. This table is that
-- memory: extract once per trial, reuse for every subsequent match,
-- until the trial's own eligibility text actually changes.
--
-- Deliberately NOT org-scoped, unlike every patient-data table in this
-- schema (patients, patient_labs, match_results, ...). A trial's
-- eligibility criteria are a fact about the trial — sourced from
-- ClinicalTrials.gov/CTRI's own public registry text — not about any
-- patient or organisation. Caching it per-org would multiply the very
-- redundant work this table exists to eliminate by the number of orgs on
-- the platform, for zero benefit: two different hospitals matching
-- against the same NCT ID should get the same cached criteria, not
-- separately pay to extract it twice. The precedent for a global,
-- service-write-managed table already exists in this schema —
-- india_site_profiles (migration 006) uses the identical
-- read-all-authenticated / service-role-write RLS shape for the same
-- reason (site profiles aren't org-specific facts either).
--
-- Self-invalidating on trial-text changes, not just NCT/CTRI-ID-keyed:
-- eligibility_text_hash is a sha256 of the exact eligibility text a
-- cache entry's criteria were extracted from. A protocol amendment that
-- changes a trial's eligibility criteria produces a different hash, so
-- the next match against that trial is a genuine cache miss — re-extract
-- and overwrite — rather than silently serving criteria that no longer
-- match the live protocol text. Keying by NCT/CTRI ID alone (with no
-- hash check) would have been simpler but wrong: a cache that can go
-- stale and never self-corrects is worse than no cache, for something
-- feeding into a clinical eligibility decision.

CREATE TABLE IF NOT EXISTS trial_criteria_cache (
  id                     uuid PRIMARY KEY DEFAULT uuid_generate_v4(),

  source                 text NOT NULL CHECK (source IN ('ClinicalTrials.gov', 'CTRI')),
  trial_id               text NOT NULL,              -- NCT ID or CTRI registration number
  eligibility_text_hash  text NOT NULL,               -- sha256 hex digest of the eligibility text these criteria came from — see header

  -- The full, final criteria set for this trial — rule-based AND
  -- AI-extracted entries already merged and deduped, in the same shape
  -- lib/eligibility-rules.ts's Criterion[] expects. Evaluation against a
  -- given patient's structured clinical data still happens fresh on
  -- every match (that part genuinely does depend on the patient) — only
  -- the extraction of WHAT the criteria are is what this table caches.
  criteria               jsonb NOT NULL DEFAULT '[]',

  -- Observability only — not read by matching logic, just makes it
  -- possible to see the rule-based/AI split for a cached trial without
  -- re-deriving it from criteria's own extractionSource-equivalent field.
  rule_based_count       int NOT NULL DEFAULT 0,
  ai_extracted_count     int NOT NULL DEFAULT 0,

  extracted_at           timestamptz NOT NULL DEFAULT now(),
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT trial_criteria_cache_unique_trial UNIQUE (source, trial_id)
);

-- No separate index needed beyond the unique constraint's own index —
-- every real lookup is `WHERE source = ? AND trial_id = ?` (optionally
-- AND eligibility_text_hash = ? for a hit-or-miss check), and
-- (source, trial_id) is exactly the unique index's leftmost columns.

CREATE OR REPLACE FUNCTION set_trial_criteria_cache_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_trial_criteria_cache_updated
  BEFORE UPDATE ON trial_criteria_cache
  FOR EACH ROW EXECUTE FUNCTION set_trial_criteria_cache_updated_at();

-- ═══════════════════════════════════════════════════════════════════
-- RLS — same shape as india_site_profiles (migration 006): this is
-- global, non-sensitive, service-managed data, not org-scoped patient
-- data. Read allowed for any authenticated user (a future coordinator UI
-- showing "criteria last extracted for this trial" could query it
-- directly); writes restricted to the service role, since only
-- lib/matcher.ts (via supabaseAdmin, server-side only) ever populates
-- this table.
-- ═══════════════════════════════════════════════════════════════════

ALTER TABLE trial_criteria_cache ENABLE ROW LEVEL SECURITY;

CREATE POLICY "trial_criteria_cache_read_all" ON trial_criteria_cache
  FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "trial_criteria_cache_service_write" ON trial_criteria_cache
  FOR ALL USING (auth.role() = 'service_role');

-- Verify
SELECT table_name, (SELECT rowsecurity FROM pg_tables WHERE tablename = table_name) AS rls_enabled
FROM information_schema.tables
WHERE table_name = 'trial_criteria_cache';
-- Expected: 1 row, rls_enabled = true

SELECT 'Migration 018 complete' AS status;


-- SOURCE: supabase/migrations/019_rate_limits.sql
-- TrialMatch India — Migration 019
-- Run AFTER 018_trial_criteria_cache.sql
--
-- Postgres-backed rate limiting
--
-- Why: lib/ratelimit.ts used a plain in-memory Map, and said so honestly
-- in its own header comment — "This Map is per-serverless-instance... does
-- NOT enforce a true global limit across all instances... an accepted
-- tradeoff for Phase 1." On Vercel, concurrent requests can land on
-- different warm instances (or trigger new cold starts), each with its
-- own empty Map, so none of this project's rate limits — the match
-- endpoint, patient creation, ABDM OTP requests, feasibility runs — were
-- reliably enforced once traffic stopped being small enough to mostly
-- land on one warm instance. This migration moves the counters into
-- Postgres, which is genuinely shared across every instance, using the
-- same "no new infrastructure" approach as everything else in this
-- project (no Redis, no new paid dependency — Supabase is already here).
--
-- Correctness under real concurrency, not just under a single request:
-- check_and_increment_rate_limit() below does the "is this window still
-- current, and should this request be counted or rejected" logic as ONE
-- atomic INSERT ... ON CONFLICT ... RETURNING statement, not a
-- read-then-write from application code. Two concurrent requests for the
-- same key genuinely serialize at the database row level — the second
-- transaction blocks until the first's write commits, then sees its
-- result — which is exactly the property a rate limiter needs and a
-- naive "SELECT count, then UPDATE if under limit" implementation does
-- not have (that shape has a real race: two concurrent requests can both
-- read the same "before" count and both decide they're allowed).

CREATE TABLE IF NOT EXISTS rate_limits (
  key       text PRIMARY KEY,
  count     int NOT NULL DEFAULT 1,
  reset_at  timestamptz NOT NULL
);

-- No separate cleanup job for expired rows — see
-- check_and_increment_rate_limit's own comment: an expired row is
-- indistinguishable from a fresh one to this function (it resets on read),
-- so stale rows are inert, not incorrect. Left in place rather than adding
-- a pg_cron job (Free-tier Supabase projects don't have pg_cron at all —
-- see notifications_and_cron.sql's own header) for a table whose rows are
-- tiny and whose count naturally stays bounded by the number of distinct
-- orgs/users/IPs actually making requests.

CREATE OR REPLACE FUNCTION check_and_increment_rate_limit(
  p_key          text,
  p_max_requests int,
  p_window_ms    int
) RETURNS TABLE(allowed boolean, remaining int, reset_in_ms bigint) LANGUAGE plpgsql AS $$
DECLARE
  v_now      timestamptz := clock_timestamp();
  v_count    int;
  v_reset_at timestamptz;
BEGIN
  INSERT INTO rate_limits (key, count, reset_at)
  VALUES (p_key, 1, v_now + (p_window_ms || ' milliseconds')::interval)
  ON CONFLICT (key) DO UPDATE SET
    count    = CASE WHEN rate_limits.reset_at <= v_now THEN 1
                     ELSE rate_limits.count + 1 END,
    reset_at = CASE WHEN rate_limits.reset_at <= v_now
                     THEN v_now + (p_window_ms || ' milliseconds')::interval
                     ELSE rate_limits.reset_at END
  RETURNING rate_limits.count, rate_limits.reset_at INTO v_count, v_reset_at;

  RETURN QUERY SELECT
    (v_count <= p_max_requests)                                        AS allowed,
    GREATEST(0, p_max_requests - v_count)                               AS remaining,
    GREATEST(0, CEIL(EXTRACT(EPOCH FROM (v_reset_at - v_now)) * 1000))::bigint AS reset_in_ms;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════
-- RLS — same shape as trial_criteria_cache (migration 018) and
-- india_site_profiles (migration 006): global, not org-scoped data
-- (a rate-limit key can be an org, a user, or a raw IP — none of those
-- map to "this row belongs to org X" the way every patient-data table
-- does), read for any authenticated caller, write restricted to the
-- service role — in practice only ever called via supabaseAdmin() from
-- lib/ratelimit.ts itself.
-- ═══════════════════════════════════════════════════════════════════

ALTER TABLE rate_limits ENABLE ROW LEVEL SECURITY;

CREATE POLICY "rate_limits_read_all" ON rate_limits
  FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "rate_limits_service_write" ON rate_limits
  FOR ALL USING (auth.role() = 'service_role');

GRANT EXECUTE ON FUNCTION check_and_increment_rate_limit TO service_role;

-- Verify
SELECT table_name FROM information_schema.tables
WHERE table_schema = 'public' AND table_name = 'rate_limits';
-- Expected: 1 row

SELECT 'Migration 019 complete' AS status;


-- SOURCE: supabase/migrations/020_match_job_limits.sql
-- TrialMatch India — Migration 020
-- Run AFTER 019_rate_limits.sql
--
-- Two related fixes, found together while wiring up match-jobs/month
-- enforcement (previously advertised in lib/plans.ts's trial-tier
-- features list, never actually enforced anywhere):
--
-- 1. max_match_jobs_per_month didn't exist as a column at all — added
--    below, matching the same per-org-overridable pattern already used
--    for max_patients/max_users (see schema.sql's organizations table
--    and lib/gate.ts's checkLimit).
--
-- 2. organizations.max_patients/max_users' column DEFAULTs never matched
--    what the 'trial' plan they default alongside actually advertises.
--    schema.sql: `max_users int default 5, max_patients int default 50`.
--    lib/plans.ts's trial tier: max_users: 2, max_patients: 10. Every
--    self-signup organization — created via
--    pages/api/auth/[...nextauth].ts's "New user" branch, which never
--    set these columns explicitly, relying entirely on these defaults —
--    silently got 2.5x the advertised team-member capacity and 5x the
--    advertised patient capacity of the free trial it was labelled as,
--    for its full lifetime on that plan. Confirmed by reading
--    schema.sql's column defaults directly against lib/plans.ts's
--    PLANS.trial values — not a guess.
--
--    Fixed at the column-default level here (defense in depth for
--    anything that ever inserts an organizations row without setting
--    these explicitly) AND, more importantly, at the actual org-creation
--    code path itself (pages/api/auth/[...nextauth].ts now sets all
--    three limits explicitly from lib/plans.ts's PLANS.trial, the single
--    source of truth, rather than depending on column defaults to happen
--    to agree with it).
--
--    Deliberately NOT touched here: any already-existing organization's
--    current max_patients/max_users values. Retroactively lowering a
--    real, already-onboarded org's limit is a support/business decision
--    (grandfather them in, or enforce the corrected cap and risk breaking
--    their workflow if they're already over it), not something a
--    migration should silently decide. Given this product has no real
--    production organizations yet (see FIXES_2026-07-27.md's Tier 5
--    disclosure), this is moot today but worth stating explicitly for
--    whenever it stops being moot.

ALTER TABLE organizations
  ADD COLUMN IF NOT EXISTS max_match_jobs_per_month int DEFAULT 5;

ALTER TABLE organizations ALTER COLUMN max_patients SET DEFAULT 10;
ALTER TABLE organizations ALTER COLUMN max_users    SET DEFAULT 2;

-- Verify
SELECT column_name, column_default
FROM information_schema.columns
WHERE table_name = 'organizations'
  AND column_name IN ('max_patients', 'max_users', 'max_match_jobs_per_month')
ORDER BY column_name;
-- Expected: max_match_jobs_per_month default 5, max_patients default 10, max_users default 2

SELECT 'Migration 020 complete' AS status;


-- SOURCE: supabase/migrations/021_org_audit_summary_view.sql
-- TrialMatch India — Migration 021
-- Run AFTER 020_match_job_limits.sql
--
-- org_audit_summary was defined in migration 011_audit_log.sql, but its
-- creation failed silently at that point in the migration chain — it
-- selects `outcome`, a column that migration 011's own CREATE TABLE IF
-- NOT EXISTS never actually added (audit_log already existed from
-- schema.sql with a different, minimal set of columns — see
-- FIXES_2026-07-27.md for the full story). Migration 016 fixed the
-- underlying columns; nothing since then re-attempted this view.
-- CREATE OR REPLACE VIEW is naturally idempotent, so this is safe to run
-- regardless of whether an earlier, partial attempt exists.

CREATE OR REPLACE VIEW org_audit_summary AS
SELECT
  org_id,
  DATE(created_at AT TIME ZONE 'Asia/Kolkata') AS day_ist,
  action,
  outcome,
  COUNT(*) AS event_count
FROM audit_log
WHERE created_at > now() - INTERVAL '90 days'
GROUP BY org_id, day_ist, action, outcome;

-- Verify
SELECT table_name FROM information_schema.views
WHERE table_schema = 'public' AND table_name = 'org_audit_summary';
-- Expected: 1 row

SELECT 'Migration 021 complete' AS status;


-- SOURCE: supabase/migrations/022_fix_match_accuracy_criteria.sql
-- TrialMatch India — Migration 022
-- Run AFTER 021_org_audit_summary_view.sql
--
-- match_accuracy_events was reported as a dormant table — "created in
-- migration 012, never written to by anything." That was half right.
-- Verified directly against a real Postgres database: the trigger
-- migration 012 already created (record_match_accuracy_event, AFTER
-- UPDATE OF enrollment_status ON match_results) genuinely fires and
-- genuinely inserts a row, correctly, every time a coordinator uses the
-- existing enrollment-status UI (components/EnrollmentStatusDropdown.tsx
-- + pages/api/match/[id].ts's PATCH handler — both already real, already
-- working, already in production code) to mark a match as enrolled,
-- screen_failed, patient_declined, or trial_closed. outcome,
-- screen_fail_reason, and nct_id all populate correctly.
--
-- What's actually broken: the trigger reads
-- `NEW.matches->0->'eligibilityDetails'` for criteria_at_match — and
-- eligibilityDetails is a field nothing in this codebase has ever
-- written (confirmed earlier this engagement: it's declared on the
-- TrialMatch type and read in two places, but no code path ever sets
-- it). So criteria_at_match has always ended up '[]', silently, on
-- every real accuracy event — confirmed directly: inserted a
-- realistic match_results row (matches JSONB shaped exactly like what
-- lib/matcher.ts actually produces, deterministicResults present,
-- eligibilityDetails absent because nothing sets it), ran the exact
-- UPDATE the coordinator PATCH handler runs, and got outcome/
-- screen_fail_reason/nct_id all correct with criteria_at_match = [].
--
-- The fix: read from `deterministicResults` instead — the field that is
-- actually populated on every real match, with a real
-- extractionSource-tagged PASS/FAIL/UNKNOWN per criterion (see
-- lib/matcher.ts). Mapped to the shape criteria_at_match's own
-- comment already documented as the intent (`match_status:
-- 'met'|'partial'|'unmet'`): PASS -> met, FAIL -> unmet,
-- UNKNOWN -> partial. `field` (loosely named in the original schema
-- comment) is populated from `evidence` — the specific data point the
-- deterministic evaluator actually examined for that criterion, the
-- closest real analogue to what that field was for.
--
-- Left unchanged, deliberately: this still only looks at matches->0 (the
-- patient's top-ranked match), matching migration 012's own original
-- design — enrollment_status is one field per match_results row (one row
-- per patient, not per trial-match), so tracking anything other than the
-- top match here would be a real, separate data-model change, not a bug
-- fix. Also unchanged: failure_predicted/failure_criterion, which
-- migration 012's own comment already scoped as "(set by nightly job)" —
-- no such job exists yet; wiring it up is real, separate future work
-- that needs criteria_at_match to actually contain data first, which is
-- exactly what this migration fixes.

CREATE OR REPLACE FUNCTION record_match_accuracy_event()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.enrollment_status IN ('enrolled','screen_failed','patient_declined','trial_closed')
     AND (OLD.enrollment_status IS DISTINCT FROM NEW.enrollment_status) THEN
    INSERT INTO match_accuracy_events (
      org_id, match_result_id, patient_id, nct_id, outcome,
      screen_fail_reason, criteria_at_match
    )
    SELECT
      NEW.org_id,
      NEW.id,
      NEW.patient_id,
      COALESCE(NEW.matches->0->>'nctId', ''),
      NEW.enrollment_status,
      NEW.screen_fail_reason,
      COALESCE(
        (SELECT jsonb_agg(jsonb_build_object(
          'criterion', elem->>'description',
          'status',    CASE elem->>'result'
                         WHEN 'PASS'    THEN 'met'
                         WHEN 'FAIL'    THEN 'unmet'
                         WHEN 'UNKNOWN' THEN 'partial'
                         ELSE 'partial'
                       END,
          'field',     elem->>'evidence'
        ))
        FROM jsonb_array_elements(NEW.matches->0->'deterministicResults') AS elem),
        '[]'::jsonb
      )
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

-- Verify
SELECT prosrc LIKE '%deterministicResults%' AS reads_the_real_field
FROM pg_proc WHERE proname = 'record_match_accuracy_event';
-- Expected: t

SELECT 'Migration 022 complete' AS status;


-- SOURCE: supabase/migrations/023_mfa.sql
-- TrialMatch India — Migration 023
-- Run AFTER 022_fix_match_accuracy_criteria.sql
--
-- TOTP-based MFA for privileged roles (owner, admin) — see lib/mfa.ts for
-- the full design rationale. This project's own Tier 4 disclosure named
-- "MFA for privileged roles" as a real, open gap.
--
-- mfa_secret_encrypted stores the TOTP secret encrypted at rest
-- (AES-256-GCM, application-layer — see lib/mfa.ts's encryptSecret/
-- decryptSecret) — never plaintext. mfa_last_time_step is what makes
-- replay protection actually work across requests: otplib's
-- afterTimeStep needs somewhere durable to read the previously-consumed
-- time step from, and a single login session can span many separate API
-- calls. mfa_backup_codes stores SHA-256 hashes only (see lib/mfa.ts's
-- hashBackupCode) — the plaintext codes are shown to the user exactly
-- once, at enrollment, and never stored.

ALTER TABLE users
  ADD COLUMN IF NOT EXISTS mfa_enabled            boolean DEFAULT false,
  ADD COLUMN IF NOT EXISTS mfa_secret_encrypted    text,
  ADD COLUMN IF NOT EXISTS mfa_backup_codes        text[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS mfa_last_time_step      bigint,
  ADD COLUMN IF NOT EXISTS mfa_enrolled_at         timestamptz;

-- Pending-enrollment secrets (generated but not yet confirmed with a
-- valid code — see pages/api/mfa/setup.ts) are stored in this same
-- mfa_secret_encrypted column before mfa_enabled flips to true; there is
-- deliberately no separate "pending secret" column. A half-finished
-- enrollment simply overwrites itself if the user starts over, and
-- mfa_enabled staying false is what determines whether a stored secret
-- is "confirmed" or "someone started enrolling and never finished" —
-- both cases behave identically (no MFA is actually enforced) until
-- mfa_enabled is explicitly set true by successful confirmation.

-- Verify
SELECT column_name FROM information_schema.columns
WHERE table_name = 'users' AND column_name LIKE 'mfa_%'
ORDER BY column_name;
-- Expected: 5 rows

SELECT 'Migration 023 complete' AS status;


-- SOURCE: supabase/migrations/024_failure_prediction.sql
-- TrialMatch India — Migration 024
-- Run AFTER 023_mfa.sql
--
-- failure_predicted / failure_criterion — the piece migration 012's own
-- comment scoped as "(set by nightly job)" and migration 022 deliberately
-- left unbuilt: "a naive version — flagging any screen-failure with any
-- unmet/partial criterion as 'predicted' — would be almost always true
-- and not meaningfully informative, and could mislead a future accuracy
-- analysis into false confidence."
--
-- What's here instead: pg_trgm lexical similarity (already enabled by
-- migration 005, no new extension) between the coordinator's own
-- screen_fail_reason text and each unmet/partial criterion's description,
-- only flagging a prediction when the best match clears a real,
-- empirically-calibrated threshold — not "any correlation exists."
--
-- Threshold calibration (run directly against real Postgres before
-- picking a number, not guessed): genuinely correlated pairs — "eGFR too
-- low at screening" vs "eGFR >= 45", "still on metformin, did not stop in
-- time" vs "No current use of metformin", "Patient HbA1c came back too
-- high" vs "HbA1c between 8.0-11.0%" — scored 0.15 to 0.25. Genuinely
-- unrelated pairs — "patient moved out of the city" vs "eGFR >= 45",
-- "lost to follow up" vs "HbA1c between 8.0-11.0%" — scored exactly 0.
-- Short/generic reason text with real false-positive risk — "not
-- eligible", "no show", "coordinator error" — scored 0 to 0.09 against
-- unrelated criteria. 0.15 sits with real margin on both sides of that
-- empirical split.
--
-- Stated honestly, not just implied: this is LEXICAL similarity (shared
-- words/substrings), not clinical reasoning. "Declined due to renal
-- function" scored 0 against "eGFR >= 45" in calibration, even though a
-- clinician would recognize the connection — trigram similarity has no
-- concept of that relationship. This will only ever flag a correlation
-- when the coordinator's own wording actually overlaps with the
-- criterion's — which is a real, common case (coordinators often do
-- reference the specific lab/medication by name), but a conservative,
-- honest subset of true correlations, not all of them. Missing a real
-- correlation (false negative, leaving failure_predicted false) is the
-- deliberately preferred failure mode over inventing one this data can't
-- actually support — the same "UNKNOWN over a guessed answer" principle
-- this whole codebase already applies to patient-eligibility evaluation
-- (see lib/eligibility-rules.ts).

CREATE OR REPLACE FUNCTION record_match_accuracy_event()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  v_criteria_at_match jsonb;
  v_failure_predicted  boolean := false;
  v_failure_criterion  text    := NULL;
  v_best_score         real;
BEGIN
  IF NEW.enrollment_status IN ('enrolled','screen_failed','patient_declined','trial_closed')
     AND (OLD.enrollment_status IS DISTINCT FROM NEW.enrollment_status) THEN

    v_criteria_at_match := COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'criterion', elem->>'description',
        'status',    CASE elem->>'result'
                       WHEN 'PASS'    THEN 'met'
                       WHEN 'FAIL'    THEN 'unmet'
                       WHEN 'UNKNOWN' THEN 'partial'
                       ELSE 'partial'
                     END,
        'field',     elem->>'evidence'
      ))
      FROM jsonb_array_elements(NEW.matches->0->'deterministicResults') AS elem),
      '[]'::jsonb
    );

    IF NEW.enrollment_status = 'screen_failed'
       AND NEW.screen_fail_reason IS NOT NULL
       AND length(trim(NEW.screen_fail_reason)) > 0 THEN
      SELECT c->>'criterion', similarity(NEW.screen_fail_reason, c->>'criterion')
      INTO v_failure_criterion, v_best_score
      FROM jsonb_array_elements(v_criteria_at_match) AS c
      WHERE c->>'status' IN ('unmet', 'partial')
      ORDER BY similarity(NEW.screen_fail_reason, c->>'criterion') DESC
      LIMIT 1;

      IF v_best_score IS NULL OR v_best_score < 0.15 THEN
        v_failure_predicted := false;
        v_failure_criterion := NULL;
      ELSE
        v_failure_predicted := true;
      END IF;
    END IF;

    INSERT INTO match_accuracy_events (
      org_id, match_result_id, patient_id, nct_id, outcome,
      screen_fail_reason, criteria_at_match, failure_predicted, failure_criterion
    )
    SELECT
      NEW.org_id,
      NEW.id,
      NEW.patient_id,
      COALESCE(NEW.matches->0->>'nctId', ''),
      NEW.enrollment_status,
      NEW.screen_fail_reason,
      v_criteria_at_match,
      -- NULL (not false) for every outcome other than screen_failed —
      -- "did the screen failure align with a criterion" is a question
      -- that only applies to a screen failure in the first place; NULL
      -- here means "not applicable," which is different from "checked
      -- and found no correlation" (false).
      CASE WHEN NEW.enrollment_status = 'screen_failed' THEN v_failure_predicted ELSE NULL END,
      v_failure_criterion
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

-- Verify
SELECT prosrc LIKE '%similarity%' AS uses_trigram_similarity
FROM pg_proc WHERE proname = 'record_match_accuracy_event';
-- Expected: t

SELECT 'Migration 024 complete' AS status;


-- SOURCE: supabase/migrations/025_audit_log_rls_fix.sql
-- TrialMatch India — Migration 025
-- Run AFTER 024_failure_prediction.sql
--
-- Two real, independently-confirmed things, found by actually running
-- the full 001→024 migration chain against a fresh Postgres database
-- rather than assuming it worked — not carried over from any prior
-- session's notes:
--
-- 1) RLS CONFLICT ON audit_log (the one that matters everywhere,
--    fresh deploy or existing one). schema.sql creates a broad
--    `org_isolation_audit` policy (FOR ALL — SELECT/INSERT/UPDATE/DELETE)
--    granting access to any member of a matching org. Migration 011
--    later defines a much narrower, intentional design for this specific
--    table — admins/owners only for SELECT, service_role only for
--    INSERT, nobody for UPDATE/DELETE — because audit_log is meant to
--    be a tamper-proof, immutable trail (its own header comment cites
--    DPDP Act 2023, ICH GCP E6(R2), and ISO 27001 for exactly this
--    property). Postgres RLS policies are permissive by default — they
--    OR together — so the old broad policy was never actually
--    superseded by the new narrow ones; it just sat alongside them,
--    silently granting every org member SELECT on the full audit log
--    (not just admins/owners), and — since no DB rule blocks INSERT the
--    way the rules below block UPDATE/DELETE — the ability to insert
--    fabricated audit rows directly, which is precisely what this
--    table's own design intends to prevent. This migration removes
--    that one policy from audit_log specifically. It is NOT touched on
--    any other table — org_isolation_* on patients, organizations, etc.
--    is the correct, intended access model there; audit_log is the one
--    table whose own design doc promises something stricter.
--
-- 2) SAFETY NET for anyone who ran the pre-fix version of 011_audit_log.sql
--    against a real project before this build. That version hard-errored
--    partway through (on a column that didn't exist yet), which aborted
--    the rest of the script in the same run — meaning RLS was never
--    enabled on audit_log, its two intended policies and two
--    tamper-prevention rules were never created, and consent_records
--    (the DPDP Act §6 consent-tracking table) never existed at all.
--    Migration 016 patched the missing columns; migration 021 patched
--    the missing view; nothing until now patched the rest. Everything
--    below is written idempotently (DROP...IF EXISTS + CREATE, IF NOT
--    EXISTS) so it's a safe no-op on a database where 011 already ran
--    cleanly (i.e. anyone deploying fresh with this build), and a real
--    fix for anyone who deployed before it.

-- ── Fix 1: remove the overly-broad policy from audit_log specifically ──
DROP POLICY IF EXISTS "org_isolation_audit" ON audit_log;

-- ── Fix 2: idempotent safety net — audit_log RLS + policies + rules ────
ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "org_admins_read_audit" ON audit_log;
CREATE POLICY "org_admins_read_audit"
  ON audit_log FOR SELECT
  USING (
    org_id = (
      SELECT org_id FROM users
      WHERE id = auth.uid() AND role IN ('admin', 'owner')
    )
    OR auth.role() = 'service_role'
  );

DROP POLICY IF EXISTS "service_role_insert_audit" ON audit_log;
CREATE POLICY "service_role_insert_audit"
  ON audit_log FOR INSERT
  WITH CHECK (auth.role() = 'service_role');

-- No UPDATE or DELETE policies — intentionally absent, same as 011.

CREATE OR REPLACE RULE no_delete_audit AS ON DELETE TO audit_log
  DO INSTEAD NOTHING;

CREATE OR REPLACE RULE no_update_audit AS ON UPDATE TO audit_log
  DO INSTEAD NOTHING;

-- ── Fix 2 continued: idempotent safety net — consent_records ───────────
CREATE TABLE IF NOT EXISTS consent_records (
  id              uuid        PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id          uuid        REFERENCES organizations(id) NOT NULL,
  patient_id      uuid        REFERENCES patients(id),
  consent_type    text        NOT NULL
    CHECK (consent_type IN (
      'data_processing', 'trial_matching', 'sponsor_aggregate',
      'pdf_report', 'whatsapp_notification', 'third_party_sharing',
      'data_retention'
    )),
  version         text        NOT NULL,
  given           boolean     NOT NULL,
  given_at        timestamptz,
  withdrawn_at    timestamptz,
  collection_method text      NOT NULL
    CHECK (collection_method IN ('verbal_logged', 'written_form', 'digital_form', 'abdm_derived')),
  collected_by    uuid        REFERENCES users(id),
  notes           text,
  evidence_ref    text,
  created_at      timestamptz DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_consent_patient  ON consent_records (patient_id, consent_type);
CREATE INDEX IF NOT EXISTS idx_consent_org      ON consent_records (org_id, given);

ALTER TABLE consent_records ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "org_isolation_consent" ON consent_records;
CREATE POLICY "org_isolation_consent"
  ON consent_records
  USING (org_id = (SELECT org_id FROM users WHERE id = auth.uid()));

-- ── Sanity check ─────────────────────────────────────────────────────
SELECT policyname, cmd FROM pg_policies WHERE tablename = 'audit_log' ORDER BY policyname;
-- Expected: exactly 2 rows — org_admins_read_audit (SELECT), service_role_insert_audit (INSERT).
-- If org_isolation_audit still appears, something above did not apply.

SELECT 'Migration 025 complete' AS status;


-- SOURCE: supabase/migrations/026_rematch_runs_rls_fix.sql
-- TrialMatch India — Migration 026
-- Run AFTER 025_audit_log_rls_fix.sql
--
-- Found during a systematic policy audit (Tier 3 security pass) of every
-- table, not just the ones that looked interesting: `rematch_runs` has
-- RLS enabled (migration 014_security_fixes.sql turned it on, correctly
-- flagging it as "the only table of 25 created without RLS") but zero
-- policies were ever added. RLS-enabled-with-no-policies means Postgres
-- default-denies everyone except the table owner and roles with
-- BYPASSRLS (service_role) — so this doesn't currently break anything,
-- since the only thing that could ever query this table is service-role
-- code, which bypasses RLS entirely regardless of policies. Confirmed
-- separately: rematch_runs is not referenced anywhere in application
-- code today (lib/rematch.ts doesn't write to it) — it's dead, matching
-- this project's own established pattern of features defined in SQL but
-- never wired up (see rxnorm.ts's history for the same class of gap,
-- now fixed). This migration doesn't wire it up — that's a product
-- decision, not a security fix — it just makes the table's access
-- control correctly defined, consistent with every other global
-- (non-org-scoped) table in this schema, so it's ready whenever
-- something does read/write it, rather than silently returning zero
-- rows to anyone who eventually tries.
--
-- Pattern matched exactly from mrr_snapshots (the other cross-org,
-- service-role-only table): FOR ALL, service_role only.

DROP POLICY IF EXISTS "service_role_only_rematch_runs" ON rematch_runs;
CREATE POLICY "service_role_only_rematch_runs"
  ON rematch_runs FOR ALL
  USING (auth.role() = 'service_role');

SELECT policyname, cmd FROM pg_policies WHERE tablename = 'rematch_runs';
-- Expected: 1 row — service_role_only_rematch_runs.

SELECT 'Migration 026 complete' AS status;


-- SOURCE: supabase/migrations/027_llm_provider_settings.sql
-- TrialMatch India — Migration 027
-- Run AFTER 026_rematch_runs_rls_fix.sql
--
-- Adds per-organization AI provider configuration. Previously the
-- matching engine was hardcoded to a single, platform-wide Anthropic
-- API key — meaning every org sharing this deployment was forced onto
-- the same vendor with no way to opt into a different one, which was
-- architecturally inconsistent with every other org-level setting this
-- schema already has (billing, branding, notification preferences).
--
-- llm_api_key_encrypted follows the exact same AES-256-GCM pattern as
-- users.mfa_secret_encrypted (see migration 023 and lib/mfa.ts), but
-- with its OWN separate encryption key (LLM_CREDENTIAL_ENCRYPTION_KEY,
-- not MFA_ENCRYPTION_KEY) — a compromised AI provider key and a
-- compromised MFA secret are different blast radii, and should never
-- share a key.
--
-- An org with llm_provider IS NULL (the default) simply uses the
-- platform-wide default provider (env vars) — nothing breaks for any
-- existing org that never configures this.

ALTER TABLE organizations
  ADD COLUMN IF NOT EXISTS llm_provider           text
    CHECK (llm_provider IS NULL OR llm_provider IN ('anthropic', 'openai', 'google', 'openai_compatible')),
  ADD COLUMN IF NOT EXISTS llm_api_key_encrypted   text,
  ADD COLUMN IF NOT EXISTS llm_model               text,
  ADD COLUMN IF NOT EXISTS llm_base_url            text,
  ADD COLUMN IF NOT EXISTS llm_configured_at       timestamptz,
  ADD COLUMN IF NOT EXISTS llm_configured_by       uuid REFERENCES users(id);

-- openai_compatible specifically requires a base URL (it's what makes
-- the endpoint identifiable at all) — every other provider has a known,
-- fixed endpoint and doesn't need one.
ALTER TABLE organizations
  DROP CONSTRAINT IF EXISTS organizations_llm_openai_compatible_needs_base_url;
ALTER TABLE organizations
  ADD CONSTRAINT organizations_llm_openai_compatible_needs_base_url
  CHECK (llm_provider IS DISTINCT FROM 'openai_compatible' OR llm_base_url IS NOT NULL);

-- Verify
SELECT column_name, data_type
FROM information_schema.columns
WHERE table_name = 'organizations'
  AND column_name LIKE 'llm_%'
ORDER BY column_name;
-- Expected: 6 rows

SELECT 'Migration 027 complete' AS status;


-- SOURCE: supabase/migrations/028_organizations_rls_fix.sql
-- TrialMatch India — Migration 028
-- Run AFTER 027_llm_provider_settings.sql
--
-- Found during continued review after adding llm_api_key_encrypted to
-- this table: organizations has exactly one RLS policy, org_self_read,
-- and it has no FOR clause — which defaults to FOR ALL. Confirmed
-- directly against the live database (not assumed): cmd = 'ALL'. That
-- means any org member, not just admin/owner, could UPDATE their org's
-- row directly if RLS were ever the live enforcement boundary — the
-- same class of gap migration 025 found and fixed for audit_log, now
-- more consequential here specifically because this table holds an
-- encrypted AI provider credential (migration 027) that pages/api/org's
-- PATCH handler already correctly restricts to admin/owner server-side.
-- This migration makes the DB-level guarantee match that server-side
-- enforcement, rather than relying on the API layer alone.
--
-- As established elsewhere in this project's own audit trail: the
-- browser never obtains a real per-user Supabase JWT here (NextAuth
-- issues its own, unrelated to and unrecognized by Supabase's
-- auth.uid()), so this isn't a currently-reachable exploit — it's
-- defense-in-depth, the same category as the audit_log fix, fixed for
-- the same reason: a policy that's broader than intended shouldn't sit
-- there just because nothing currently reaches it.
--
-- No INSERT/DELETE policy is added, intentionally — organizations are
-- created via the signup flow using the service-role client (which
-- bypasses RLS entirely), never by a regular authenticated user
-- directly, and should never be deletable by one either.

DROP POLICY IF EXISTS "org_self_read" ON organizations;

DROP POLICY IF EXISTS "org_members_read" ON organizations;
CREATE POLICY "org_members_read"
  ON organizations FOR SELECT
  USING (id = (SELECT org_id FROM users WHERE id = auth.uid()));

DROP POLICY IF EXISTS "org_admins_update" ON organizations;
CREATE POLICY "org_admins_update"
  ON organizations FOR UPDATE
  USING (
    id = (SELECT org_id FROM users WHERE id = auth.uid() AND role IN ('admin', 'owner'))
    OR auth.role() = 'service_role'
  );

-- Verify
SELECT policyname, cmd FROM pg_policies WHERE tablename = 'organizations' ORDER BY policyname;
-- Expected: exactly 2 rows — org_members_read (SELECT), org_admins_update (UPDATE)

SELECT 'Migration 028 complete' AS status;

